-- =============================================================================
-- 501 — LE CAHIER D'EXERCICES DE 2DE (partie 3)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 501 --niveau 2de --fichiers allemand.n1,anglais.n1,anglais.n2 --suffixe 3 > supabase/contenu/501_exercices_2de_3.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.n1             36 exercices · 12 chapitres
--   anglais.n1              30 exercices · 10 chapitres
--   anglais.n2              30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('5ae68ba3-3b82-57d0-a239-2e9bbaf7919d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois pays, trois drapeaux","competence":"lire-tableau","situation":"Pour son exposé, Camille prépare une fiche sur les emblèmes des pays germanophones. Elle a commencé un tableau : à toi de le lire.","documents":[{"id":"embl","type":"tableau","titre":"Drei Länder, drei Fahnen","colonnes":["Pays","Drapeau","À savoir"],"lignes":[["Deutschland","schwarz-rot-gold","couleurs de la démocratie de 1848, reprises par la RFA en 1949"],["Österreich","rot-weiß-rot","l’un des plus anciens drapeaux d’Europe"],["Schweiz","weißes Kreuz auf rotem Grund","26 cantons, chacun avec ses armoiries"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la case qui décrit le drapeau de l’Autriche.","aide":"Cherche la ligne « Österreich », puis la colonne « Drapeau ».","type":"zone","document":"embl","multiple":false},{"enonce":"Touche la case qui indique combien de cantons compte la Suisse.","aide":"Les cantons sont cités dans la colonne « À savoir ».","type":"zone","document":"embl","multiple":false},{"enonce":"Relie chaque mot allemand à son sens.","aide":"Pense à *Wappen* : chaque canton suisse en a un.","type":"association","gauche":[{"id":"g0","texte":"das Wappen"},{"id":"g1","texte":"die Tracht"},{"id":"g2","texte":"das Selbstporträt"},{"id":"g3","texte":"die Herkunft"}],"droite":[{"id":"d0","texte":"l’autoportrait"},{"id":"d1","texte":"les armoiries"},{"id":"d2","texte":"l’origine"},{"id":"d3","texte":"le costume traditionnel"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le drapeau autrichien est **rot-weiß-rot** (rouge, blanc, rouge) : on le lit sur la ligne « Österreich », colonne « Drapeau »."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"La Suisse compte **26 cantons**, chacun avec ses armoiries (*das Wappen*) : l’information est dans la colonne « À savoir »."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**das Wappen** = les armoiries, **die Tracht** = le costume traditionnel, **das Selbstporträt** = l’autoportrait, **die Herkunft** = l’origine."}]$ex$::jsonb),
  ('5ae68ba3-3b82-57d0-a239-2e9bbaf7919d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’été où les drapeaux ont fleuri","competence":"analyser-texte","situation":"Kim prépare un exposé sur le rapport des Allemands à leurs symboles nationaux. Elle a trouvé un court article sur l’été 2006 et doit en comprendre l’idée.","documents":[{"id":"art","type":"texte","genre":"article","titre":"Der Sommer der Fahnen","blocs":["Im Sommer 2006 findet die Fußballweltmeisterschaft in Deutschland statt. Plötzlich hängen überall schwarz-rot-goldene Fahnen: an Fenstern, an Autos und auf Balkonen.","Das ist neu. Nach 1945 haben viele Deutsche ihre nationalen Symbole nur selten gezeigt, denn Patriotismus war lange verdächtig.","Manche Journalisten nennen das einen Partypatriotismus: Man feiert, und die Fahne gehört zum Fest."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot allemand qui désigne les drapeaux dans le premier paragraphe.","aide":"Cherche ce qu’on accroche aux fenêtres et aux balcons.","type":"zone","document":"art","multiple":false},{"enonce":"Pourquoi la scène décrite par l’article est-elle une nouveauté ?","aide":"Relis le deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"Avant 2006, le drapeau allemand avait des couleurs différentes"},{"id":"b","texte":"Après 1945, les Allemands montraient rarement leurs symboles nationaux"},{"id":"c","texte":"Les drapeaux étaient interdits dans les stades allemands"},{"id":"d","texte":"En 2006, c’était la première Coupe du monde de football"}],"multiple":false},{"enonce":"Touche le mot allemand qui correspond à « patriotisme de fête ».","aide":"C’est un mot composé : *Party* + *Patriotismus*.","type":"zone","document":"art","multiple":false},{"enonce":"Dans un exposé, un élève écrit « Alle Deutschen sind pünktlich. Das ist ein Klischee. » Que veut-il dire ?","aide":"*das Klischee* ressemble à un mot français.","type":"choix","options":[{"id":"a","texte":"Que cette règle est écrite dans la loi allemande"},{"id":"b","texte":"Que cette phrase est une vieille chanson"},{"id":"c","texte":"Que tous les Allemands arrivent en avance"},{"id":"d","texte":"Que cette idée est un cliché, une image toute faite"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**Fahnen** est le pluriel de *die Fahne*, le drapeau : ce sont elles qui « hängen » partout pendant la Coupe du monde."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’article le dit : **après 1945, le patriotisme était resté longtemps suspect** et les symboles nationaux se montraient peu. En 2006, ils reviennent en force."},{"cle":{"type":"zone","ids":["m45"]},"explication":"**Partypatriotismus** : le patriotisme de fête. On brandit le drapeau pour faire la fête, pas pour affirmer une doctrine."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Das ist ein Klischee** : c’est un cliché. Le cours en cite plusieurs (ordre, ponctualité, bière) et invite à les regarder avec recul."}]$ex$::jsonb),
  ('5ae68ba3-3b82-57d0-a239-2e9bbaf7919d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Se montrer : du Christ à la Tracht","competence":"analyser-document","situation":"Pour le cours d’allemand, Noé compare plusieurs façons de se montrer : le portrait de soi d’un artiste, le costume d’une fête, le drapeau d’un pays. Il a rassemblé une frise et l’affiche d’une fête.","documents":[{"id":"frise","type":"frise","titre":"Se représenter à travers les siècles","debut":1500,"fin":2100,"pas":100,"evenements":[{"id":"z1","date":1500,"nom":"Autoportrait Dürer"},{"id":"z2","date":1810,"nom":"1er Oktoberfest"},{"id":"z3","date":1890,"nom":"Naissance de Schiele"},{"id":"z4","date":1949,"nom":"Noir-rouge-or RFA"},{"id":"z5","date":2006,"nom":"Coupe du monde"}],"source":"Dates tirées du cours"},{"id":"affiche","type":"fiche","modele":"affiche","entete":"Oktoberfest München","sousTitre":"Tracht-Abend für Jugendliche","emoji":"🥨","teinte":"ambre","lignes":[{"texte":"Seit 1810 gibt es das Oktoberfest in München.","id":"z6"},{"separateur":true},{"texte":"Dirndl und Lederhose sind willkommen.","id":"z7"},{"texte":"Auch in Jeans bist du dabei!","id":"z8"}],"pied":"Tradition oder Mode? Das entscheidest du!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’événement où un artiste se peint avec une pose réservée jusque-là au Christ.","aide":"C’est le plus ancien événement de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’autoportrait de Dürer de la naissance d’Egon Schiele ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Touche la ligne de l’affiche qui indique depuis quand existe la fête.","aide":"Cherche la date.","type":"zone","document":"affiche","multiple":false},{"enonce":"Relie chaque élément à ce qu’il montre ou signifie.","aide":"Dürer s’affirme, Schiele avoue un malaise.","type":"association","gauche":[{"id":"g0","texte":"Dürer, 1500"},{"id":"g1","texte":"Schiele"},{"id":"g2","texte":"Dirndl et Lederhose"},{"id":"g3","texte":"Noir, rouge, or"}],"droite":[{"id":"d0","texte":"costumes régionaux de Bavière et d’Autriche"},{"id":"d1","texte":"se peint de face, main sur la poitrine"},{"id":"d2","texte":"se montre maigre, tordu, presque nu"},{"id":"d3","texte":"couleurs de la démocratie de 1848"}]},{"enonce":"Un camarade dit : « Un autoportrait, un drapeau ou un costume montrent simplement la réalité. » Que lui réponds-tu d’après le cours ?","aide":"Relis la phrase du cours sur ce qu’on montre et ce qu’on cache.","type":"choix","options":[{"id":"a","texte":"Seul l’autoportrait peut cacher quelque chose"},{"id":"b","texte":"Tu as raison : on ne peut rien y cacher"},{"id":"c","texte":"Seul le costume est choisi, le drapeau ne l’est jamais"},{"id":"d","texte":"Ils montrent surtout l’image qu’on choisit de donner"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"En **1500**, Albrecht Dürer se peint de face, cheveux longs, main sur la poitrine : la pose du Christ. Il affirme la dignité du créateur."},{"cle":{"type":"nombre","valeur":390,"tolerance":0},"affichage":"390 ans","explication":"1890 − 1500 = **390 ans**, soit environ quatre siècles : c’est le « quatre siècles plus tard » du cours."},{"cle":{"type":"zone","ids":["z6"]},"explication":"La fête existe **depuis 1810** (*seit 1810*) : l’Oktoberfest de Munich est plus ancien que bien des traditions qu’on croit éternelles."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**Dürer** s’affirme avec dignité ; **Schiele** avoue un malaise intérieur ; le **Tracht** est un costume régional ; **noir-rouge-or** sont les couleurs de la démocratie de 1848."},{"cle":{"type":"choix","ids":["d"]},"explication":"Se représenter, c’est **choisir ce qu’on montre et ce qu’on cache** : ces trois objets parlent autant de l’image voulue que de la réalité."}]$ex$::jsonb),
  ('5d8e5f36-5636-5ef7-a2cc-48026a7f9cc4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un étudiant cherche une chambre","competence":"comprendre-langue","situation":"Dans le couloir de la fac, Mila lit une affiche en allemand. Elle veut comprendre de quel type de logement il s’agit.","documents":[{"id":"aff","type":"fiche","modele":"affiche","entete":"Zimmer gesucht – Hilfe geboten","sousTitre":"Ein Angebot für Studierende","emoji":"🏠","teinte":"turquoise","lignes":[{"texte":"Du bist Student und suchst ein Zimmer?","id":"z1"},{"texte":"Eine Seniorin sucht Hilfe im Garten und beim Einkaufen.","id":"z2"},{"separateur":true},{"texte":"Du wohnst bei ihr. Statt Miete hilfst du ihr im Alltag.","id":"z3"}],"pied":"So können Jung und Alt voneinander lernen.","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui dit ce que l’étudiant donne en échange du logement.","aide":"Cherche le mot « Miete » (le loyer).","type":"zone","document":"aff","multiple":false},{"enonce":"De quelle forme de vie ensemble parle cette affiche ?","aide":"Un étudiant loge chez un senior… contre quoi ?","type":"choix","options":[{"id":"a","texte":"Senioren-WG"},{"id":"b","texte":"Wohnen für Hilfe"},{"id":"c","texte":"Generationenvertrag"},{"id":"d","texte":"Mehrgenerationenhaus"}],"multiple":false},{"enonce":"Relie chaque mot de la famille à sa traduction.","aide":"Pense à *WG*, qu’on entend souvent.","type":"association","gauche":[{"id":"g0","texte":"die Großeltern"},{"id":"g1","texte":"die Enkel"},{"id":"g2","texte":"die Rente"},{"id":"g3","texte":"die Wohngemeinschaft"}],"droite":[{"id":"d0","texte":"les petits-enfants"},{"id":"d1","texte":"la colocation"},{"id":"d2","texte":"la retraite"},{"id":"d3","texte":"les grands-parents"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"À la place d’un loyer, l’étudiant **aide la personne âgée au quotidien** : c’est le principe de la ligne « Statt Miete hilfst du ihr im Alltag »."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est **Wohnen für Hilfe** : un étudiant est logé chez un senior contre de l’aide. Une *Senioren-WG* réunit des personnes âgées entre elles."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**die Großeltern** = les grands-parents, **die Enkel** = les petits-enfants, **die Rente** = la retraite, **die Wohngemeinschaft** (WG) = la colocation."}]$ex$::jsonb),
  ('5d8e5f36-5636-5ef7-a2cc-48026a7f9cc4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Opa Peter et le Mai 68 allemand","competence":"analyser-document","situation":"Jonas prépare un exposé sur 1968 en Allemagne. Il écrit à son grand-père, qui était adolescent à l’époque.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Jonas","emoji":"👦","cote":"gauche"},{"nom":"Opa Peter","emoji":"👴","cote":"droite"}],"repliques":[{"qui":"Jonas","texte":"Opa, in meinem Geschichtskurs sprechen wir über 1968. Warst du dabei?"},{"qui":"Opa Peter","texte":"Ich war noch Schüler, aber meine älteren Freunde haben protestiert. Ihr Slogan war: „Trau keinem über 30!“"},{"qui":"Jonas","texte":"Und was wollten sie von ihren Eltern wissen?"},{"qui":"Opa Peter","texte":"Sie fragten: Was habt ihr im Nationalsozialismus gemacht?"},{"qui":"Jonas","texte":"Heute demonstrieren wir für das Klima. Manche sagen, das ist ein Generationenkonflikt."},{"qui":"Opa Peter","texte":"Vielleicht. Aber ich komme zur nächsten Demo mit! Wir können voneinander lernen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot allemand qui désigne le régime sur lequel les étudiants interrogeaient leurs parents.","aide":"C’est un très long mot, dans la réponse d’Opa Peter.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète le slogan de 1968 cité dans la conversation.","aide":"Le slogan vise les plus âgés.","type":"trous","segments":["Trau keinem ",0," 30!"],"banque":["nach","vor","über","unter"]},{"enonce":"Range chaque élément dans le mouvement auquel il appartient.","aide":"Un mouvement parle du passé des parents, l’autre de l’avenir de la planète.","type":"categories","categories":[{"id":"c0","texte":"1968"},{"id":"c1","texte":"Fridays for Future"}],"items":[{"id":"i0","texte":"Question sur le rôle des parents sous le nazisme"},{"id":"i1","texte":"« Trau keinem über 30 ! »"},{"id":"i2","texte":"Luisa Neubauer"},{"id":"i3","texte":"Reproche : laisser une planète abîmée"},{"id":"i4","texte":"Omas for Future"},{"id":"i5","texte":"Rudi Dutschke"}]},{"enonce":"Opa Peter conclut : « Wir können voneinander lernen. » Que propose-t-il ?","aide":"*voneinander* = les uns des autres.","type":"choix","options":[{"id":"a","texte":"Que les générations vivent séparées"},{"id":"b","texte":"Que chaque génération apprenne de l’autre"},{"id":"c","texte":"Que les anciens se taisent"},{"id":"d","texte":"Que les jeunes obéissent aux anciens"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m42"]},"explication":"Les jeunes de 1968 demandaient : « Qu’avez-vous fait sous le **Nationalsozialismus** ? » Beaucoup d’anciens nazis occupaient encore des postes importants."},{"cle":{"type":"trous","trous":[["uber"]]},"affichage":"über","explication":"**Trau keinem über 30 !** : « Ne fais confiance à personne de plus de 30 ans ». *über* signifie « au-dessus de »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"**1968** : Rudi Dutschke, la question sur le nazisme, le slogan. **Fridays for Future** : Luisa Neubauer, le reproche sur la planète, et les grands-mères d’*Omas for Future*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Wir können voneinander lernen** : « nous pouvons apprendre les uns des autres ». Le conflit entre générations est aussi une forme de transmission."}]$ex$::jsonb),
