  ('38809e26-c505-5e51-a8cf-9e7d05be194a'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Marcher sur des pavés de laiton","competence":"analyser-texte","situation":"Clara est en voyage scolaire en Allemagne. Elle raconte sa visite dans une rue où le sol « parle ». Lis son récit.","documents":[{"id":"blog","type":"texte","genre":"article","titre":"Unser Klassenausflug","blocs":["Heute waren wir mit der Klasse unterwegs. Auf dem Gehweg vor einem Haus habe ich kleine Platten aus Messing gesehen.","Das sind Stolpersteine. Auf jedem Stein stehen der Name und das Schicksal eines Opfers des Nationalsozialismus. Man legt sie vor das letzte Wohnhaus der Person.","Der Künstler Demnig hatte die Idee. Man muss den Kopf beugen, um den Namen zu lesen: Man „stolpert“ mit den Augen."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne la matière dont sont faites les plaques.","aide":"Les plaques sont brillantes : c’est un alliage de cuivre.","type":"zone","document":"blog","multiple":false},{"enonce":"Touche le nom de l’artiste qui a eu l’idée des Stolpersteine.","aide":"Le nom suit le mot « Künstler ».","type":"zone","document":"blog","multiple":false},{"enonce":"Complète la phrase d’après le texte.","aide":"Relis le deuxième paragraphe.","type":"trous","segments":["Man legt die Steine vor das letzte ",0," der Person."],"banque":["Wohnhaus","Krankenhaus","Büro","Gymnasium"]},{"enonce":"Pourquoi appelle-t-on ces pavés « Stolpersteine » (pierres sur lesquelles on trébuche) ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Ils sont posés au milieu de la chaussée pour bloquer les voitures"},{"id":"b","texte":"On « trébuche » du regard en se penchant pour lire le nom"},{"id":"c","texte":"Les enfants doivent sauter par-dessus pendant la visite"},{"id":"d","texte":"Les pavés dépassent du sol et font tomber les passants"}],"multiple":false},{"enonce":"Relie chaque mot allemand à sa traduction.","aide":"*das Erbe* est ce qu’on reçoit de ceux qui nous précèdent.","type":"association","gauche":[{"id":"g0","texte":"die Vergangenheit"},{"id":"g1","texte":"die Erinnerung"},{"id":"g2","texte":"die Schuld"},{"id":"g3","texte":"das Erbe"}],"droite":[{"id":"d0","texte":"la culpabilité"},{"id":"d1","texte":"le souvenir"},{"id":"d2","texte":"l’héritage"},{"id":"d3","texte":"le passé"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Les Stolpersteine sont des pavés de **Messing**, le laiton."},{"cle":{"type":"zone","ids":["m47"]},"explication":"L’artiste est **Gunter Demnig** ; son nom de famille, *Demnig*, apparaît dans le dernier paragraphe."},{"cle":{"type":"trous","trous":[["wohnhaus"]]},"affichage":"Wohnhaus","explication":"Les pavés sont posés devant le **dernier domicile** (*das Wohnhaus*) de la victime."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le but n’est pas de faire tomber : on **trébuche du regard** en baissant la tête pour lire un nom. « Un homme n’est oublié que lorsque son nom est oublié. »"},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"**die Vergangenheit** = le passé, **die Erinnerung** = le souvenir, **die Schuld** = la culpabilité, **das Erbe** = l’héritage."}]$ex$::jsonb),
  ('38809e26-c505-5e51-a8cf-9e7d05be194a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Ostalgie, mines et mémoire","competence":"analyser-document","situation":"Lucie compare deux façons de vivre avec l’histoire : celle d’une habitante de Leipzig, née en RDA, et celle de lieux qui ont changé de rôle. Lis les deux documents.","documents":[{"id":"weber","type":"texte","genre":"article","titre":"Frau Weber erzählt","blocs":["Frau Weber, 52, ist in Leipzig aufgewachsen. Sie erzählt:","„Nach der Wiedervereinigung 1990 hat sich alles verändert. Ich vermisse nicht die Stasi und nicht die Diktatur. Aber ich vermisse die Solidarität im Haus und die Sicherheit des Arbeitsplatzes.“","Dann lacht sie: „Wenn ich im Film Good Bye, Lenin! die alten Produkte sehe, bin ich ein bisschen traurig. Das nennt man Ostalgie.“"],"source":"Entretien imaginé pour l’exercice"},{"id":"lieux","type":"tableau","titre":"Orte im Wandel","colonnes":["Lieu","Région","Avant","Aujourd’hui"],"lignes":[["Zollverein","Essen, dans la Ruhr","mine de charbon","site culturel classé par l’UNESCO (2001)"],["Lusace","à l’est du pays","région du charbon","cherche encore son avenir"],["Ampelmännchen","ex-RDA","bonhomme des feux piétons de l’Est","sauvé par la mobilisation des Berlinois"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui désigne la police politique que Frau Weber ne regrette pas.","aide":"Elle dit ne regretter ni elle ni la dictature.","type":"zone","document":"weber","multiple":false},{"enonce":"Frau Weber regrette-t-elle la dictature de la RDA ?","aide":"Relis ce qu’elle dit vermissen (regretter).","type":"choix","options":[{"id":"a","texte":"Oui : elle voudrait que la RDA revienne"},{"id":"b","texte":"Oui : elle regrette la Stasi et les contrôles"},{"id":"c","texte":"Non : elle regrette seulement les voyages à l’étranger"},{"id":"d","texte":"Non : elle regrette la solidarité et la sécurité de l’emploi"}],"multiple":false},{"enonce":"Touche la case qui dit que la mine de charbon d’Essen est aujourd’hui reconnue par l’UNESCO.","aide":"Cherche la ligne « Zollverein », colonne « Aujourd’hui ».","type":"zone","document":"lieux","multiple":false},{"enonce":"Range chaque description dans la région qui lui correspond.","aide":"Une région a trouvé une nouvelle vie, l’autre cherche encore.","type":"categories","categories":[{"id":"c0","texte":"Ruhr (Essen)"},{"id":"c1","texte":"Lusace"}],"items":[{"id":"i0","texte":"Une mine devenue site culturel classé par l’UNESCO"},{"id":"i1","texte":"Une région où l’on se demande encore ce qui remplacera le charbon"},{"id":"i2","texte":"Une région de l’est qui cherche encore son avenir après le charbon"},{"id":"i3","texte":"Un ancien lieu de travail ouvert aux visiteurs et aux musées"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Elle ne regrette pas la **Stasi**, la police politique de la RDA : regretter la vie d’avant n’est pas regretter la dictature."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’**Ostalgie** n’est pas un regret de la dictature : Frau Weber regrette des choses précises (la solidarité, la sécurité de l’emploi) et pas la Stasi."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"**Zollverein**, à Essen, est devenue un site culturel classé au patrimoine mondial de l’UNESCO en 2001."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"La **Ruhr** a transformé ses friches en sites culturels (Zollverein) ; la **Lusace**, à l’est, cherche encore son avenir après le charbon."}]$ex$::jsonb),
  ('7218dfa3-6b7f-5130-8e2c-e7a581f93e89'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le tournant énergétique en quatre dates","competence":"se-reperer-temps","situation":"Pour un exposé, Samir a placé les grandes étapes de l’Energiewende sur une frise. À toi de la lire.","documents":[{"id":"frise","type":"frise","titre":"Die Energiewende","debut":2000,"fin":2040,"pas":10,"evenements":[{"id":"z1","date":2000,"nom":"Loi EEG"},{"id":"z2","date":2011,"nom":"Sortie du nucléaire"},{"id":"z3","date":2023,"nom":"Derniers réacteurs"},{"id":"z4","date":2038,"nom":"Fin du charbon"}],"source":"Dates tirées du cours (la fin du charbon est prévue « au plus tard » en 2038)"}],"questions":[{"enonce":"Touche l’étape décidée après la catastrophe de Fukushima.","aide":"Fukushima a lieu en 2011.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la décision de sortir du nucléaire de l’arrêt des derniers réacteurs ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque mot allemand à sa traduction.","aide":"*Kern* se traduit par « noyau », donc atomique.","type":"association","gauche":[{"id":"g0","texte":"die Energiewende"},{"id":"g1","texte":"das Kernkraftwerk"},{"id":"g2","texte":"erneuerbare Energien"},{"id":"g3","texte":"der Klimawandel"}],"droite":[{"id":"d0","texte":"les énergies renouvelables"},{"id":"d1","texte":"le changement climatique"},{"id":"d2","texte":"le tournant énergétique"},{"id":"d3","texte":"la centrale nucléaire"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Après la catastrophe de **Fukushima** (2011), l’Allemagne décide de sortir du nucléaire : c’est l’étape « Sortie du nucléaire »."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 ans","explication":"2023 − 2011 = **12 ans** entre la décision et l’arrêt des trois derniers réacteurs."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**die Energiewende** = le tournant énergétique, **das Kernkraftwerk** = la centrale nucléaire, **erneuerbare Energien** = les énergies renouvelables, **der Klimawandel** = le changement climatique."}]$ex$::jsonb),
  ('7218dfa3-6b7f-5130-8e2c-e7a581f93e89'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Du vent du nord à l’industrie du sud","competence":"lire-carte","situation":"Léa observe une carte de l’Allemagne et lit un court texte : le vent souffle surtout au nord, mais où l’électricité est-elle consommée ? Elle cherche à comprendre un problème du tournant énergétique.","documents":[{"id":"karte","type":"carte","titre":"Deutschland: Wind und Industrie","fond":"europe","cadrage":[4,46,17,56],"regions":[{"code":"DEU","teinte":"sable","etiquette":"Deutschland"}],"lieux":[{"id":"z1","lieu":"hambourg","symbole":"lettre","lettre":"A","teinte":"bleu"},{"id":"z2","lieu":"munich","symbole":"lettre","lettre":"B","teinte":"corail"}],"traits":[{"points":["hambourg","munich"],"style":"fleche","teinte":"violet"}],"source":"Fond de carte simplifié"},{"id":"strom","type":"texte","genre":"article","titre":"Strom aus Wind","blocs":["Im Norden Deutschlands weht oft starker Wind. Dort stehen viele Windräder.","Die Industrie braucht den Strom aber vor allem im Süden. Deshalb muss das Stromnetz ausgebaut werden. Das kostet viel Geld.","Außerdem hängt das Land noch von Kohle und Gas ab."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Le vent est fort dans le nord du pays. Touche sur la carte la ville située au nord.","aide":"Le nord est en haut de la carte.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche sur la carte la ville du sud, où l’industrie a besoin de beaucoup d’électricité.","aide":"Le sud est en bas de la carte.","type":"zone","document":"karte","multiple":false},{"enonce":"Que représente la flèche tracée entre le nord et le sud ?","aide":"Relis le deuxième paragraphe du texte.","type":"choix","options":[{"id":"a","texte":"Le courant du fleuve qui traverse le pays"},{"id":"b","texte":"La route du charbon vers les centrales nucléaires"},{"id":"c","texte":"Le trajet des touristes qui vont dans les Alpes"},{"id":"d","texte":"Le réseau électrique à reconstruire du nord vers le sud"}],"multiple":false},{"enonce":"Touche le mot allemand qui signifie « le réseau électrique ».","aide":"C’est un mot composé : *Strom* + *Netz*.","type":"zone","document":"strom","multiple":false},{"enonce":"Complète la phrase d’après le texte.","aide":"Relis la première phrase du deuxième paragraphe.","type":"trous","segments":["Die Industrie braucht den Strom vor allem im ",0,"."],"banque":["Westen","Osten","Norden","Süden"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La ville **A**, Hambourg, est tout au nord : c’est là que le vent produit beaucoup d’électricité."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La ville **B**, Munich, est dans le sud : l’industrie y consomme beaucoup, comme le dit le texte."},{"cle":{"type":"choix","ids":["d"]},"explication":"La flèche montre le **réseau électrique** à reconstruire (*das Stromnetz*) pour amener l’électricité du vent du nord vers l’industrie du sud."},{"cle":{"type":"zone","ids":["m24"]},"explication":"**Stromnetz** : *der Strom* (le courant) + *das Netz* (le réseau)."},{"cle":{"type":"trous","trous":[["suden"]]},"affichage":"Süden","explication":"L’industrie est surtout dans le **sud** (*im Süden*), alors que le vent est au nord : d’où le réseau à reconstruire."}]$ex$::jsonb),
  ('7218dfa3-6b7f-5130-8e2c-e7a581f93e89'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Peu d’enfants, beaucoup de défis","competence":"analyser-document","situation":"Dans un forum de classe, Jonas présente deux défis : celui d’un pays qui vieillit, et celui d’un village des Alpes où la neige manque. Lis les deux documents.","documents":[{"id":"kette","type":"chaine","titre":"Warum fehlen Fachkräfte?","disposition":"ligne","noeuds":[{"id":"z1","texte":"1,4 Kind pro Frau","emoji":"👶"},{"id":"z2","texte":"Weniger junge Menschen"},{"id":"z3","texte":"Fachkräftemangel"},{"id":"z4","texte":"?"}],"liens":[{"de":"z1","a":"z2","texte":"führt zu"},{"de":"z2","a":"z3","texte":"führt zu"},{"de":"z3","a":"z4","texte":"eine Antwort"}],"source":"Schéma écrit pour l’exercice, d’après le cours"},{"id":"forum","type":"dialogue","modele":"sms","titre":"Forum: Skigebiet in Gefahr","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"In unserem Dorf in den Alpen fehlt der Schnee. Wir brauchen Schneekanonen, sonst kommen keine Touristen."},{"qui":"Ben","texte":"Das kostet viel Energie. Besser: Wandern und Mountainbike im Sommer."},{"qui":"Mia","texte":"Und was machen wir im Winter?"},{"qui":"Ben","texte":"Wir stehen vor einer großen Herausforderung. Es lohnt sich, neue Ideen zu probieren."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le maillon qui désigne la pénurie de main-d’œuvre qualifiée.","aide":"Ce mot commence par *Fachkräfte*.","type":"zone","document":"kette","multiple":false},{"enonce":"Quelle réponse du cours doit compléter le dernier maillon de la chaîne ?","aide":"Le cours cite une réponse qui fait venir du monde de l’extérieur.","type":"choix","options":[{"id":"a","texte":"La fermeture de toutes les écoles"},{"id":"b","texte":"Le retour massif au charbon"},{"id":"c","texte":"L’immigration de travailleurs qualifiés"},{"id":"d","texte":"L’arrêt complet des retraites"}],"multiple":false},{"enonce":"Touche le mot allemand qui désigne la solution défendue par Mia.","aide":"Mia veut fabriquer de la neige.","type":"zone","document":"forum","multiple":false},{"enonce":"Touche les deux activités que Ben propose pour l’été.","aide":"Ben parle de marcher et de rouler en montagne.","type":"zone","document":"forum","multiple":true},{"enonce":"Complète l’expression de Ben.","aide":"Cette expression veut dire « cela vaut la peine ».","type":"trous","segments":["Es ",0," sich, neue Ideen zu probieren."],"banque":["geht","lohnt","kostet","hilft"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Fachkräftemangel** : la pénurie de main-d’œuvre qualifiée, conséquence d’une population qui compte peu de jeunes."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pour combler le manque de main-d’œuvre, une des réponses est l’**immigration** de travailleurs qualifiés."},{"cle":{"type":"zone","ids":["m11"]},"explication":"Mia veut des **Schneekanonen** (canons à neige) pour sauver la saison d’hiver."},{"cle":{"type":"zone","ids":["m21","m23"]},"explication":"Ben propose **Wandern** (la randonnée) et **Mountainbike** (le VTT) : une reconversion vers l’été."},{"cle":{"type":"trous","trous":[["lohnt"]]},"affichage":"lohnt","explication":"**Es lohnt sich, …** : « cela vaut la peine de… ». C’est l’expression du cours pour défendre une piste d’avenir."}]$ex$::jsonb),
  ('fee03f30-f26b-575e-9a22-e29e7393ddb2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Comment est née la Loreley","competence":"lire-tableau","situation":"Au cours d’allemand, Inès retrace la naissance d’un mythe du Rhin : le rocher de la Loreley. Elle a rempli un petit tableau.","documents":[{"id":"lore","type":"tableau","titre":"Die Loreley","colonnes":["Année","Qui ?","Ce que cela ajoute"],"lignes":[[1801,"Clemens Brentano","il invente la figure de Lore Lay, une jeune femme"],[1824,"Heinrich Heine","il en fait une sirène qui peigne ses cheveux d’or et fait sombrer les bateliers"],["ensuite","Friedrich Silcher","il met le poème en musique : tous les Allemands connaissent la chanson"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche l’auteur du poème de 1824 qui fait de la Loreley une sirène.","aide":"Cherche la ligne de l’année 1824.","type":"zone","document":"lore","multiple":false},{"enonce":"Combien d’années séparent la Lore Lay de Brentano du poème de Heine ?","aide":"Soustrais les deux années du tableau.","type":"nombre","unite":"ans"},{"enonce":"Touche la case qui nomme celui qui a mis le poème en musique.","aide":"Cherche la ligne « ensuite ».","type":"zone","document":"lore","multiple":false},{"enonce":"Complète le premier vers célèbre du poème de Heine.","aide":"Le verbe veut dire « signifier ».","type":"trous","segments":["Ich weiß nicht, was soll es ",0,", dass ich so traurig bin."],"banque":["sagen","machen","bedeuten","heißen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**Heinrich Heine** publie son poème en 1824 : la Loreley y est une sirène aux cheveux d’or qui fait sombrer les bateliers."},{"cle":{"type":"nombre","valeur":23,"tolerance":0},"affichage":"23 ans","explication":"1824 − 1801 = **23 ans**."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**Friedrich Silcher** a composé la mélodie : grâce à lui, le poème est devenu une chanson que tous les Allemands connaissent."},{"cle":{"type":"trous","trous":[["bedeuten"]]},"affichage":"bedeuten","explication":"**Ich weiß nicht, was soll es bedeuten, / Dass ich so traurig bin** : « Je ne sais pas ce que cela veut dire, que je sois si triste ». *bedeuten* = signifier."}]$ex$::jsonb),
  ('fee03f30-f26b-575e-9a22-e29e7393ddb2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Faust : du vrai savant au pacte avec le diable","competence":"se-reperer-temps","situation":"Au théâtre, Yanis reçoit le programme de Faust de Goethe. Pour comprendre d’où vient cette histoire, il consulte une frise et lit l’introduction.","documents":[{"id":"frise","type":"frise","titre":"Die Geschichte von Faust","debut":1450,"fin":1850,"pas":50,"periodes":[{"id":"z1","debut":1480,"fin":1541,"nom":"Faust réel","teinte":"brun"}],"evenements":[{"id":"z2","date":1587,"nom":"Volksbuch"},{"id":"z3","date":1808,"nom":"Faust I (Goethe)"}],"source":"Dates tirées du cours (la vie de Faust : vers 1480-1541)"},{"id":"prog","type":"texte","genre":"article","titre":"Theaterprogramm","blocs":["Im Theater läuft Goethes Faust. Der Gelehrte Faust ist unzufrieden: Er will alles wissen. Er wettet mit Mephisto, dem Teufel.","Berühmt ist dieser Satz: „Zwei Seelen wohnen, ach! in meiner Brust.“ Faust fühlt sich zerrissen.","Heute nennt man einen Menschen mit grenzenlosem Ehrgeiz „faustisch“."],"source":"Texte écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la version de 1587 où Faust signe un pacte avec le diable et est damné.","aide":"Le titre de cette version est un « livre populaire ».","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le Volksbuch de 1587 du Faust I de Goethe ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot allemand qui signifie « âmes ».","aide":"Il est dans la phrase célèbre entre guillemets.","type":"zone","document":"prog","multiple":false},{"enonce":"Que dit la phrase « Zwei Seelen wohnen, ach! in meiner Brust » ?","aide":"Le programme dit que Faust se sent *zerrissen* (déchiré).","type":"choix","options":[{"id":"a","texte":"Faust est déchiré entre deux désirs contraires"},{"id":"b","texte":"Faust a signé deux pactes différents"},{"id":"c","texte":"Faust a deux frères qui vivent avec lui"},{"id":"d","texte":"Faust se sent heureux et en paix"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **Volksbuch** de **1587** raconte que Faust signe un pacte avec le diable et finit damné."},{"cle":{"type":"nombre","valeur":221,"tolerance":0},"affichage":"221 ans","explication":"1808 − 1587 = **221 ans**."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**Seelen** : « âmes ». « Zwei Seelen wohnen, ach! in meiner Brust » : deux âmes habitent ma poitrine."},{"cle":{"type":"choix","ids":["a"]},"explication":"La phrase dit le **déchirement humain** : deux âmes habitent la même poitrine. Le mot *faustisch* désigne, lui, une ambition sans limite."}]$ex$::jsonb),
  ('fee03f30-f26b-575e-9a22-e29e7393ddb2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Du Petit Chaperon rouge à la série Dark","competence":"analyser-document","situation":"Maëlle prépare une présentation sur la forêt dans l’imaginaire allemand. Elle a un texte sur les contes et la série Dark, et un tableau qui montre comment les mythes sont repris.","documents":[{"id":"wald","type":"texte","genre":"article","titre":"Der Wald in der Fantasie","blocs":["1812 erscheinen die Märchen der Brüder Grimm. Im Wald verirren sich Hänsel und Gretel, im Wald trifft Rotkäppchen den Wolf. Der Wald ist der Ort der Prüfung.","Die Romantiker lieben die Waldeinsamkeit: Der Wald ist für sie ein geheimnisvoller Zufluchtsort.","2017 spielt die Serie Dark in einem Wald bei der fiktiven Stadt Winden. Dort gibt es Höhlen, und Kinder verschwinden."],"source":"Texte écrit pour l’exercice, d’après le cours"},{"id":"mythen","type":"tableau","titre":"Mythen heute","colonnes":["Figure","Origine","Reprises aujourd’hui"],"lignes":[["Loreley","Brentano (1801), puis Heine (1824)","chansons pop, publicités, rocher très visité"],["Faust","alchimiste réel, Volksbuch (1587), Goethe (1808)","opéras, films, BD : le chercheur prêt à tout"],["Siegfried","Chanson des Nibelungen (vers 1200)","marques, jeux vidéo, bières"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot allemand qui dit ce que la forêt représente pour les héros des contes.","aide":"Hänsel et Gretel s’y perdent, le Petit Chaperon rouge y rencontre le loup.","type":"zone","document":"wald","multiple":false},{"enonce":"Combien d’années séparent la publication des contes des Grimm de la série Dark ?","aide":"Soustrais les deux années du texte.","type":"nombre","unite":"ans"},{"enonce":"Range chaque élément dans l’œuvre où on le rencontre.","aide":"Une œuvre est très ancienne, l’autre est une série récente.","type":"categories","categories":[{"id":"c0","texte":"Contes des Grimm (1812)"},{"id":"c1","texte":"Série Dark (2017)"}],"items":[{"id":"i0","texte":"Des enfants disparaissent près de la ville fictive de Winden"},{"id":"i1","texte":"Le Petit Chaperon rouge rencontre le loup"},{"id":"i2","texte":"Des grottes cachent un secret dans la forêt"},{"id":"i3","texte":"Hänsel et Gretel se perdent dans la forêt"}]},{"enonce":"Touche la case qui montre que Siegfried est devenu un produit commercial.","aide":"Cherche la ligne « Siegfried », colonne « Reprises ».","type":"zone","document":"mythen","multiple":false},{"enonce":"Un camarade dit : « Reprendre un mythe, c’est le copier. » Que montre ce tableau ?","aide":"Compare les « reprises » de chaque figure : sont-elles identiques ?","type":"choix","options":[{"id":"a","texte":"Les mythes ne changent jamais depuis le Moyen Âge"},{"id":"b","texte":"Chaque époque transforme le mythe selon ses préoccupations"},{"id":"c","texte":"Les reprises ont toutes la même forme"},{"id":"d","texte":"Seuls les chercheurs peuvent reprendre un mythe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"La forêt est le lieu de l’**épreuve** : *die Prüfung*. Les héros s’y perdent ou y rencontrent un danger."},{"cle":{"type":"nombre","valeur":205,"tolerance":0},"affichage":"205 ans","explication":"2017 − 1812 = **205 ans** : la forêt reste un lieu mythique à travers les époques."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Les **contes** de 1812 : Hänsel et Gretel, le Petit Chaperon rouge. La série **Dark** (2017) : Winden, ses grottes, ses enfants disparus."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Siegfried inspire aujourd’hui des **marques, des jeux vidéo, des bières** : « le mythe devient produit »."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Recréer n’est pas copier** : Faust devient chercheur prêt à tout, Loreley passe en chanson pop, Siegfried en marque. Chaque reprise parle de l’époque qui la fait."}]$ex$::jsonb),
  ('bc69cf7f-eda0-5ad0-a94f-43541f150383'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les neuf voisins de l’Allemagne","competence":"lire-carte","situation":"En voyage scolaire, Hugo observe la carte de l’Allemagne. Elle a plus de voisins que n’importe quel autre pays d’Europe.","documents":[{"id":"karte","type":"carte","titre":"Deutschland und seine Nachbarn","fond":"europe","cadrage":[-3,44,25,58],"regionsCliquables":true,"regions":[{"code":"DEU","teinte":"sable","etiquette":"Deutschland"}],"source":"Fond de carte simplifié"}],"questions":[{"enonce":"Touche la Pologne, le voisin de l’est.","aide":"Elle est à droite de l’Allemagne sur la carte.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche le Danemark, le voisin du nord.","aide":"Il est tout en haut, au bout d’une péninsule.","type":"zone","document":"karte","multiple":false},{"enonce":"Compte les pays qui ont une frontière commune avec l’Allemagne. Combien y en a-t-il ?","aide":"Fais le tour de l’Allemagne : nord, est, sud, ouest.","type":"nombre"},{"enonce":"Relie chaque mot allemand à sa traduction.","aide":"*Handel* est le mot qui sert aux marchands.","type":"association","gauche":[{"id":"g0","texte":"der Nachbar"},{"id":"g1","texte":"die Grenze"},{"id":"g2","texte":"der Handel"},{"id":"g3","texte":"die Zusammenarbeit"}],"droite":[{"id":"d0","texte":"le commerce"},{"id":"d1","texte":"la coopération"},{"id":"d2","texte":"la frontière"},{"id":"d3","texte":"le voisin"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["POL"]},"explication":"La **Pologne** est le grand voisin de l’est : c’est devenu un partenaire économique majeur de l’Allemagne."},{"cle":{"type":"zone","ids":["DNK"]},"explication":"Le **Danemark** est le seul voisin de l’Allemagne au nord, entre la mer du Nord et la Baltique."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"L’Allemagne a **9 voisins** : le Danemark, la Pologne, la Tchéquie, l’Autriche, la Suisse, la France, le Luxembourg, la Belgique et les Pays-Bas."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"**der Nachbar** = le voisin, **die Grenze** = la frontière, **der Handel** = le commerce, **die Zusammenarbeit** = la coopération."}]$ex$::jsonb),
  ('bc69cf7f-eda0-5ad0-a94f-43541f150383'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Sur les routes de la Hanse","competence":"analyser-document","situation":"Clara, de Hambourg, écrit à une amie française. Pour la comprendre, regarde la carte des villes et comptoirs de la Hanse.","documents":[{"id":"karte","type":"carte","titre":"Handelsstädte der Hanse","fond":"europe","cadrage":[-4,49,34,62],"lieux":[{"id":"z1","lon":-0.13,"lat":51.51,"nom":"Londres","symbole":"point"},{"id":"z2","lon":3.22,"lat":51.21,"nom":"Bruges","symbole":"point"},{"id":"z3","lon":5.32,"lat":60.39,"nom":"Bergen","symbole":"point"},{"id":"z4","lon":31.27,"lat":58.52,"nom":"Novgorod","symbole":"point"},{"id":"z5","lon":10.69,"lat":53.87,"nom":"Lübeck","symbole":"etoile","teinte":"corail"}],"source":"Carte simplifiée, d’après le cours"},{"id":"brief","type":"texte","genre":"lettre","titre":"Ein Brief aus Hamburg","blocs":["Liebe Camille, ich schreibe dir aus Hamburg! Auf unserem Auto steht HH. Das H bedeutet Hansestadt: Hamburg war früher Mitglied der Hanse.","In Bremen steht HB auf den Autos, aus demselben Grund. Viele Menschen finden das sehr schön."],"source":"Lettre écrite pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la ville surnommée la « reine de la Hanse ».","aide":"Elle est marquée d’une étoile, sur la côte de la Baltique.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche le comptoir hanséatique le plus à l’est de la carte.","aide":"Pense à la Russie.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche le mot allemand que rappelle la lettre « H » des plaques HH et HB.","aide":"Le mot commence par *Hanse-*.","type":"zone","document":"brief","multiple":false},{"enonce":"Relie chaque plaque ou chaque nom à ce qu’il désigne.","aide":"Les plaques viennent des initiales de *Hansestadt* + la ville.","type":"association","gauche":[{"id":"g0","texte":"HH"},{"id":"g1","texte":"HB"},{"id":"g2","texte":"Lübeck"},{"id":"g3","texte":"die Hanse"}],"droite":[{"id":"d0","texte":"Brême"},{"id":"d1","texte":"une association de villes marchandes"},{"id":"d2","texte":"Hambourg"},{"id":"d3","texte":"la « reine de la Hanse »"}]},{"enonce":"Range chaque mot : est-ce une marchandise de la Hanse ou une ville hanséatique ?","aide":"La Hanse vendait du sel, du hareng, du bois, des fourrures.","type":"categories","categories":[{"id":"c0","texte":"Marchandise"},{"id":"c1","texte":"Ville hanséatique"}],"items":[{"id":"i0","texte":"Salz"},{"id":"i1","texte":"Bremen"},{"id":"i2","texte":"Lübeck"},{"id":"i3","texte":"Hamburg"},{"id":"i4","texte":"Hering"},{"id":"i5","texte":"Pelze"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"**Lübeck** était la « reine de la Hanse » : l’association de villes marchandes de la mer du Nord et de la Baltique."},{"cle":{"type":"zone","ids":["z4"]},"explication":"C’est **Novgorod** : la Hanse avait des comptoirs jusqu’en Russie, mais aussi à Londres, à Bruges et à Bergen."},{"cle":{"type":"zone","ids":["m15"]},"explication":"**Hansestadt** : « ville hanséatique ». Hambourg (HH) et Brême (HB) rappellent ainsi leur passé de villes de la Hanse."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"**HH** = Hansestadt Hamburg, **HB** = Hansestadt Bremen, **Lübeck** = la reine de la Hanse, **die Hanse** = une association de villes marchandes."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"La Hanse commerçait le **sel** (*Salz*), le **hareng** (*Hering*), le bois et les **fourrures** (*Pelze*) ; **Lübeck, Hambourg et Brême** sont des villes hanséatiques."}]$ex$::jsonb),
  ('bc69cf7f-eda0-5ad0-a94f-43541f150383'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"De la CECA à l’euro, de l’Ouest à l’Est","competence":"analyser-document","situation":"Pour un débat sur l’Europe, Amélie réunit une frise et un court article. L’Allemagne est-elle le « moteur » de l’Union, ou un pays qui inquiète parfois ses voisins ?","documents":[{"id":"frise","type":"frise","titre":"Die Europäische Einigung","debut":1950,"fin":2010,"pas":10,"evenements":[{"id":"z1","date":1951,"nom":"CECA"},{"id":"z2","date":1957,"nom":"Traités de Rome"},{"id":"z3","date":1963,"nom":"Traité de l’Élysée"},{"id":"z4","date":1989,"nom":"Rideau de fer tombe"},{"id":"z5","date":2002,"nom":"L’euro"}],"source":"Dates tirées du cours"},{"id":"lok","type":"texte","genre":"article","titre":"Lokomotive der EU?","blocs":["Seit dem Fall des Eisernen Vorhangs 1989 und der EU-Erweiterung 2004 sind Polen, Tschechien und Ungarn wichtige Partner Deutschlands. Deutsche Firmen haben dort Fabriken gebaut, und Studenten fahren zum Austausch nach Warschau und Prag.","Deutschland ist das bevölkerungsreichste Land der EU, mit etwa 84 Millionen Einwohnern. Seine Nachbarn erwarten, dass es führt. Sie haben aber auch Angst, dass es dominiert."],"source":"Article écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche l’étape qui fonde la CEE.","aide":"Les traités portent le nom d’une capitale.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent les traités de Rome de l’arrivée de l’euro dans les porte-monnaie ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot allemand qui désigne ce que les entreprises allemandes ont construit en Europe de l’Est.","aide":"Ce sont des lieux où l’on produit des objets.","type":"zone","document":"lok","multiple":false},{"enonce":"Que dit l’article de l’attitude des voisins envers l’Allemagne ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Ils attendent qu’elle entraîne mais craignent qu’elle domine"},{"id":"b","texte":"Ils veulent qu’elle quitte l’Union européenne"},{"id":"c","texte":"Ils lui reprochent d’être trop petite pour peser"},{"id":"d","texte":"Ils n’ont aucune opinion sur son rôle"}],"multiple":false},{"enonce":"Range chaque élément : avant ou après la chute du rideau de fer en 1989 ?","aide":"Compare les dates de la frise à 1989.","type":"categories","categories":[{"id":"c0","texte":"Avant 1989"},{"id":"c1","texte":"Après 1989"}],"items":[{"id":"i0","texte":"La CECA"},{"id":"i1","texte":"La Pologne devient un partenaire économique majeur"},{"id":"i2","texte":"L’euro remplace le mark"},{"id":"i3","texte":"Les traités de Rome"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Les **traités de Rome** (1957) fondent la Communauté économique européenne (CEE)."},{"cle":{"type":"nombre","valeur":45,"tolerance":0},"affichage":"45 ans","explication":"2002 − 1957 = **45 ans**."},{"cle":{"type":"zone","ids":["m23"]},"explication":"Les firmes allemandes ont construit des **Fabriken** (usines) en Pologne, en Tchéquie ou en Hongrie : les échanges économiques se sont développés."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’Allemagne est la première économie et le pays le plus peuplé de l’UE : ses voisins **attendent qu’elle entraîne, mais craignent qu’elle domine**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"**Avant 1989** : la CECA (1951) et les traités de Rome (1957). **Après 1989** : l’euro (2002) et l’essor des liens avec la Pologne."}]$ex$::jsonb),
  ('fcbde816-6447-525b-8c07-7cf09823fbd5'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Du parfait au regret : le tableau de Noah","competence":"manier-langue","situation":"Noah prépare une fiche de grammaire. Pour chaque phrase au parfait, il écrit ce qu’elle devient quand on regrette ou qu’on imagine le passé. Quelques cases restent à remplir.","documents":[{"id":"konj","type":"tableau","titre":"Vom Perfekt zum Konjunktiv II","colonnes":["Perfekt","Konjunktiv II passé","Français"],"lignes":[["ich habe gelernt","ich ? gelernt","j’aurais appris"],["er ist gefahren","er ? gefahren","il serait parti en voiture"],["wir haben gesehen","wir hätten gesehen","nous aurions vu"],["sie sind geblieben","sie ? geblieben","elles seraient restées"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche, dans la colonne du parfait, les deux formes construites avec sein.","aide":"Cherche *ist* et *sind*.","type":"zone","document":"konj","multiple":true},{"enonce":"Complète les deux premières cases vides du tableau.","aide":"Au parfait : *haben* ou *sein* ? Garde le même auxiliaire.","type":"trous","segments":["ich ",0," gelernt\ner ",1," gefahren"],"banque":["war","hatte","hätte","wäre"]},{"enonce":"Pourquoi dit-on « wir hätten gesehen » et non « wir wären gesehen » ?","aide":"Regarde la colonne du parfait : *wir haben gesehen*.","type":"choix","options":[{"id":"a","texte":"Parce que wir demande toujours hätten"},{"id":"b","texte":"Parce que sehen se forme avec haben au parfait"},{"id":"c","texte":"Parce que le sujet wir est au pluriel"},{"id":"d","texte":"Parce que sehen est un verbe de mouvement"}],"multiple":false},{"enonce":"Relie chaque forme du parfait à l’auxiliaire qui la remplace au subjonctif II passé.","aide":"Le *h* de *haben* reste un *h*, le *s* de *sein* devient un *w*.","type":"association","gauche":[{"id":"g0","texte":"ich habe …"},{"id":"g1","texte":"wir haben …"},{"id":"g2","texte":"ich bin …"},{"id":"g3","texte":"wir sind …"}],"droite":[{"id":"d0","texte":"ich wäre …"},{"id":"d1","texte":"wir wären …"},{"id":"d2","texte":"ich hätte …"},{"id":"d3","texte":"wir hätten …"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r3c0"]},"explication":"Au parfait, **er ist gefahren** et **sie sind geblieben** se forment avec *sein* : ce sont des verbes de mouvement ou de changement d’état."},{"cle":{"type":"trous","trous":[["hatte"],["ware"]]},"affichage":"hätte · wäre","explication":"**ich hätte gelernt** (parfait avec *haben*) et **er wäre gefahren** (parfait avec *sein*). Ne confonds pas *hätte* (j’aurais) et *hatte* (j’avais)."},{"cle":{"type":"choix","ids":["b"]},"explication":"On garde **le même auxiliaire qu’au parfait** : *wir haben gesehen* devient *wir hätten gesehen*. *Haben* donne *hätte*, *sein* donne *wäre*."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**habe → hätte**, **haben → hätten**, **bin → wäre**, **sind → wären**."}]$ex$::jsonb),
  ('fcbde816-6447-525b-8c07-7cf09823fbd5'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le concert que Lena a raté","competence":"comprendre-langue","situation":"Lena a raté un concert. Tim, qui y était, s’étonne. Lis leur conversation, puis manipule les phrases.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Wie war das Konzert gestern, Tim?"},{"qui":"Tim","texte":"Genial! Warum bist du nicht gekommen?"},{"qui":"Lena","texte":"Ich habe für die Prüfung gelernt. Wenn ich Zeit gehabt hätte, wäre ich gekommen."},{"qui":"Tim","texte":"Du hättest mich anrufen sollen! Wir wären zusammen gegangen."},{"qui":"Lena","texte":"Fast wäre ich gekommen, aber der Bus ist nicht gefahren."},{"qui":"Tim","texte":"Schade! Beim nächsten Mal."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’auxiliaire conjugué qui termine la subordonnée introduite par wenn.","aide":"Dans une subordonnée, l’auxiliaire conjugué vient en dernier.","type":"zone","document":"sms","multiple":false},{"enonce":"Que exprime la phrase de Tim « Du hättest mich anrufen sollen ! » ?","aide":"*sollen* est le verbe du devoir.","type":"choix","options":[{"id":"a","texte":"Une condition : si Lena l’appelait"},{"id":"b","texte":"Un souhait pour le futur"},{"id":"c","texte":"Un regret de Tim sur son propre comportement"},{"id":"d","texte":"Un reproche : Lena aurait dû l’appeler"}],"multiple":false},{"enonce":"Que veut dire la phrase de Lena « Fast wäre ich gekommen » ?","aide":"*fast* signifie « presque ».","type":"choix","options":[{"id":"a","texte":"Je viendrai peut-être demain"},{"id":"b","texte":"J’ai failli venir"},{"id":"c","texte":"Je suis venue presque tous les jours"},{"id":"d","texte":"Je ne voulais pas venir"}],"multiple":false},{"enonce":"Remets les mots dans l’ordre pour reconstituer la phrase de Lena. Le premier groupe est « Wenn ich ».","aide":"Dans la subordonnée, l’auxiliaire est à la fin ; la principale commence par son verbe.","type":"ordre","items":[{"id":"a","texte":"gekommen"},{"id":"b","texte":"Zeit"},{"id":"c","texte":"gehabt hätte,"},{"id":"d","texte":"ich"},{"id":"e","texte":"wäre"},{"id":"f","texte":"Wenn ich"}]},{"enonce":"Complète le regret de Lena.","aide":"Après *hätte*, il faut un participe II.","type":"trous","segments":["Hätte ich doch früher ",0,"!"],"banque":["anrufst","anrief","anrufen","angerufen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"Dans **Wenn ich Zeit gehabt hätte**, l’auxiliaire conjugué *hätte* est rejeté à la fin de la subordonnée, après le participe *gehabt*."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est un **reproche** : « tu aurais dû m’appeler ». Le subjonctif II passé sert aussi à dire ce qu’on aurait dû faire."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Fast wäre ich gekommen** : « j’ai failli venir ». Avec *fast* + subjonctif II passé, on dit ce qui a failli arriver."},{"cle":{"type":"ordre","ids":["f","b","c","e","d","a"]},"explication":"**Wenn ich Zeit gehabt hätte, wäre ich gekommen.** Dans la principale qui suit la subordonnée, le verbe *wäre* est en tête, avant le sujet."},{"cle":{"type":"trous","trous":[["angerufen"]]},"affichage":"angerufen","explication":"**Hätte ich doch früher angerufen !** : « si seulement j’avais appelé plus tôt ». Le regret se forme avec *hätte* + participe II."}]$ex$::jsonb),
  ('fcbde816-6447-525b-8c07-7cf09823fbd5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un train raté, quatre façons de le regretter","competence":"manier-langue","situation":"Noah a raté son train. Il écrit à son colocataire Max, puis range ses phrases et complète un tableau de formes. Lis les deux documents.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Eine Nachricht an Max","blocs":["Lieber Max,","gestern war ein schrecklicher Tag! Ich habe den Zug verpasst, weil ich zu spät losgegangen bin.","Wenn ich früher aufgestanden wäre, hätte ich den Zug nicht verpasst. Hätte ich doch auf meinen Wecker gehört!","Du hättest mich wecken sollen! Fast wäre ich zu Fuß zum Bahnhof gegangen, aber es hat geregnet.","Bis bald, Noah"],"source":"Message écrit pour l’exercice"},{"id":"aux","type":"tableau","titre":"Hätte und wäre","colonnes":["Sujet","haben","sein"],"lignes":[["ich","hätte","wäre"],["du","hättest","wär(e)st"],["er/sie/es","hätte","wäre"],["wir","hätten","wären"],["ihr","?","?"],["sie/Sie","hätten","wären"]],"enteteLignes":true,"source":"Tableau d’après le cours"}],"questions":[{"enonce":"Range chaque phrase de la lettre selon son emploi du subjonctif II passé.","aide":"Cherche *doch*, *sollen*, *fast* et *wenn*.","type":"categories","categories":[{"id":"c0","texte":"Condition irréelle"},{"id":"c1","texte":"Regret"},{"id":"c2","texte":"Reproche"},{"id":"c3","texte":"Ce qui a failli arriver"}],"items":[{"id":"i0","texte":"Du hättest mich wecken sollen!"},{"id":"i1","texte":"Wenn ich früher aufgestanden wäre, hätte ich den Zug nicht verpasst."},{"id":"i2","texte":"Fast wäre ich zu Fuß zum Bahnhof gegangen."},{"id":"i3","texte":"Hätte ich doch auf meinen Wecker gehört!"}]},{"enonce":"Remets les mots dans l’ordre : « Si j’étais arrivé à l’heure, j’aurais attrapé le train. » Le premier groupe est « Wenn ich ».","aide":"L’auxiliaire de la subordonnée est à la fin ; la principale commence par *hätte*.","type":"ordre","items":[{"id":"a","texte":"hätte"},{"id":"b","texte":"gekommen wäre,"},{"id":"c","texte":"Wenn ich"},{"id":"d","texte":"ich"},{"id":"e","texte":"erreicht"},{"id":"f","texte":"pünktlich"},{"id":"g","texte":"den Zug"}]},{"enonce":"Complète la phrase avec les formes de la 2e personne du pluriel (ihr).","aide":"Regarde les autres lignes du tableau pour retrouver la terminaison de *ihr*.","type":"trous","segments":["Wenn ihr früher losgegangen ",0,", ",1," ihr den Zug erreicht."],"banque":["hätten","wäre","hättest","wärt","hättet","wären"]},{"enonce":"Quelle est la traduction de « Ich hätte den Zug verpasst » ?","aide":"Un seul tréma change le sens : *hatte* = j’avais, *hätte* = j’aurais.","type":"choix","options":[{"id":"a","texte":"Je rate le train"},{"id":"b","texte":"J’aurais raté le train"},{"id":"c","texte":"J’ai raté le train"},{"id":"d","texte":"J’avais raté le train"}],"multiple":false},{"enonce":"Pourquoi Noah écrit-il « wäre … aufgestanden » mais « hätte … verpasst » ?","aide":"Pense aux phrases au parfait : *ich bin aufgestanden*, *ich habe verpasst*.","type":"choix","options":[{"id":"a","texte":"Parce que hätte est plus poli que wäre"},{"id":"b","texte":"Au parfait, aufstehen se forme avec sein et verpassen avec haben"},{"id":"c","texte":"Parce que la phrase commence par wenn"},{"id":"d","texte":"Parce que aufstehen est séparable et verpassen ne l’est pas"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c3","i3":"c1"}},"explication":"*Wenn … wäre, hätte …* : condition irréelle ; *Hätte ich doch …* : regret ; *Du hättest … sollen* : reproche ; *Fast wäre …* : ce qui a failli arriver."},{"cle":{"type":"ordre","ids":["c","f","b","a","d","g","e"]},"explication":"**Wenn ich pünktlich gekommen wäre, hätte ich den Zug erreicht.** *kommen* se forme avec *sein* (*wäre*), *erreichen* avec *haben* (*hätte*)."},{"cle":{"type":"trous","trous":[["wart","waret"],["hattet"]]},"affichage":"wärt · hättet","explication":"**ihr wär(e)t** (*losgehen* se forme avec *sein*) et **ihr hättet** (*erreichen* avec *haben*) : la terminaison de *ihr* est *-t*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Ich hätte den Zug verpasst** = « j’aurais raté le train ». Avec *hatte* (sans tréma), ce serait « j’avais raté le train » : un fait réel."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’auxiliaire du subjonctif II passé suit celui du parfait : **aufstehen** → *ich bin aufgestanden* → *wäre* ; **verpassen** → *ich habe verpasst* → *hätte*."}]$ex$::jsonb),
  ('5468a974-5a8d-5ed8-8285-f239695567ce'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un verbe, une préposition, un cas","competence":"manier-langue","situation":"Amel recopie dans son cahier quelques couples verbe + préposition, qu’il faut apprendre comme un seul mot. Lis son tableau.","documents":[{"id":"rek","type":"tableau","titre":"Verben mit Präposition","colonnes":["Verbe","Préposition + cas","Français"],"lignes":[["warten","auf + acc.","attendre"],["denken","an + acc.","penser à"],["Angst haben","vor + dat.","avoir peur de"],["teilnehmen","an + dat.","participer à"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la case qui donne la préposition de warten.","aide":"Cherche la ligne « warten ».","type":"zone","document":"rek","multiple":false},{"enonce":"Touche la case qui montre que teilnehmen an se construit avec le datif.","aide":"Il y a deux lignes avec *an* : regarde le cas.","type":"zone","document":"rek","multiple":false},{"enonce":"Complète la phrase avec les bonnes prépositions.","aide":"Relis le tableau pour *warten* et *denken*.","type":"trous","segments":["Wir warten ",0," den Bus und denken ",1," die Ferien."],"banque":["an","auf","vor","über"]},{"enonce":"Relie chaque verbe avec sa préposition à sa traduction.","aide":"La préposition fait partie du sens : apprends-la avec le verbe.","type":"association","gauche":[{"id":"g0","texte":"sich kümmern um"},{"id":"g1","texte":"abhängen von"},{"id":"g2","texte":"träumen von"},{"id":"g3","texte":"beitragen zu"}],"droite":[{"id":"d0","texte":"s’occuper de"},{"id":"d1","texte":"rêver de"},{"id":"d2","texte":"contribuer à"},{"id":"d3","texte":"dépendre de"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"**warten auf** + accusatif : en français « attendre » n’a pas de préposition, l’allemand en exige une."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**teilnehmen an** + datif : *Ich nehme an einer Debatte teil.* Pour *denken an*, c’est l’accusatif."},{"cle":{"type":"trous","trous":[["auf"],["an"]]},"affichage":"auf · an","explication":"**warten auf** + acc. et **denken an** + acc. : *Wir warten auf den Bus und denken an die Ferien.*"},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"**sich kümmern um** = s’occuper de, **abhängen von** = dépendre de, **träumen von** = rêver de, **beitragen zu** = contribuer à."}]$ex$::jsonb),
  ('5468a974-5a8d-5ed8-8285-f239695567ce'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un débat à préparer","competence":"comprendre-langue","situation":"Mara et Ole préparent un débat de classe sur le climat. Dans leur conversation, plusieurs verbes sont suivis d’une préposition précise.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Mara","emoji":"👧","cote":"gauche"},{"nom":"Ole","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mara","texte":"Hast du Lust, an der Debatte in der Schule teilzunehmen?"},{"qui":"Ole","texte":"Ja! Und was ist das Thema?"},{"qui":"Mara","texte":"Wir diskutieren über den Klimawandel. Ich interessiere mich sehr für dieses Thema."},{"qui":"Ole","texte":"Ich freue mich schon auf die Debatte! Aber ich habe ein bisschen Angst vor dem Mikrofon."},{"qui":"Mara","texte":"Keine Sorge. Wir treffen uns um 16 Uhr in der Aula."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui accompagne sich interessieren.","aide":"Mara dit qu’elle s’intéresse à un thème.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche la préposition qui accompagne Angst haben.","aide":"Ole a peur du micro.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Ole écrit-il « Ich freue mich schon auf die Debatte » ?","aide":"Pense au moment où a lieu le débat.","type":"choix","options":[{"id":"a","texte":"Parce que Debatte est un mot féminin"},{"id":"b","texte":"Auf remplace toujours über avec ce verbe"},{"id":"c","texte":"Le débat est passé : auf exprime un souvenir"},{"id":"d","texte":"Le débat est à venir : auf exprime une joie future"}],"multiple":false},{"enonce":"Complète la question qui porte sur le thème de la discussion.","aide":"*diskutieren über* : la question porte sur une chose.","type":"trous","segments":[0," diskutieren Mara und Ole? — Über den Klimawandel."],"banque":["Auf wen","Worüber","Wovon","Woran"]},{"enonce":"Mara écrit « an der Debatte teilzunehmen ». Pourquoi « der » et non « die » ?","aide":"Regarde la ligne *teilnehmen* du cours.","type":"choix","options":[{"id":"a","texte":"Parce que teilnehmen an est suivi du datif"},{"id":"b","texte":"Parce que an indique un mouvement vers la salle"},{"id":"c","texte":"Parce que l’infinitif impose le datif"},{"id":"d","texte":"Parce que Debatte est un nom masculin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25"]},"explication":"**sich interessieren für** + accusatif : *Ich interessiere mich für dieses Thema.*"},{"cle":{"type":"zone","ids":["m41"]},"explication":"**Angst haben vor** + datif : *Angst vor dem Mikrofon.*"},{"cle":{"type":"choix","ids":["d"]},"explication":"**sich freuen auf** + acc. : se réjouir d’une chose **à venir** ; **sich freuen über** : se réjouir d’une chose présente ou passée."},{"cle":{"type":"trous","trous":[["woruber"]]},"affichage":"Worüber","explication":"**Worüber diskutieren Mara und Ole ?** *diskutieren über* + acc. ; pour une chose, on forme la question avec *wor-* + *über*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**teilnehmen an** + **datif** : *an der Debatte* (datif féminin = *der*). Le cas est fixé par le verbe, pas par un lieu ou un mouvement."}]$ex$::jsonb),
  ('5468a974-5a8d-5ed8-8285-f239695567ce'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre aux parents, une joie à nuancer","competence":"manier-langue","situation":"La classe de Frau Keller part à Vienne. Lis la lettre qu’elle envoie aux parents, puis la conversation de deux élèves : plusieurs verbes y exigent une préposition précise.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Ein Brief an die Eltern","blocs":["Liebe Eltern,","die Klasse 2b fährt im Mai für eine Woche nach Wien. Alle Schüler können an der Fahrt teilnehmen.","Wir bitten Sie um eine Antwort bis Freitag. Die Kosten hängen von der Zimmerwahl ab. Die Schüler müssen sich selbst um ihre Ausweise kümmern.","Mit freundlichen Grüßen, Frau Keller"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Hannah","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Hannah","texte":"Nächste Woche fahren wir nach Wien! Ich freue mich so auf die Reise."},{"qui":"Jan","texte":"Danke für deine Postkarte aus Berlin! Ich freue mich über deine Nachricht."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui exprime la joie d’une chose à venir.","aide":"Hannah parle d’un voyage qui n’a pas encore eu lieu.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche la préposition qui exprime la joie d’une chose présente ou passée.","aide":"Jan a déjà reçu la carte postale.","type":"zone","document":"sms","multiple":false},{"enonce":"Relie chaque verbe de la lettre à sa traduction.","aide":"Chaque verbe de la lettre est suivi d’une préposition différente.","type":"association","gauche":[{"id":"g0","texte":"teilnehmen an"},{"id":"g1","texte":"sich kümmern um"},{"id":"g2","texte":"abhängen von"},{"id":"g3","texte":"bitten um"}],"droite":[{"id":"d0","texte":"dépendre de"},{"id":"d1","texte":"participer à"},{"id":"d2","texte":"s’occuper de"},{"id":"d3","texte":"demander (quelque chose)"}]},{"enonce":"Range chaque phrase : est-elle correcte ou fausse ?","aide":"Cherche chaque couple verbe + préposition dans ton cours.","type":"categories","categories":[{"id":"c0","texte":"Correcte"},{"id":"c1","texte":"Fausse"}],"items":[{"id":"i0","texte":"Er ist verantwortlich für die Gruppe."},{"id":"i1","texte":"Sie träumt von einer Reise."},{"id":"i2","texte":"Ich interessiere mich an Musik."},{"id":"i3","texte":"Sie hat Angst auf dem Hund."},{"id":"i4","texte":"Ich kümmere mich um meinen Bruder."},{"id":"i5","texte":"Wir warten für den Zug."}]},{"enonce":"Complète la phrase.","aide":"*sprechen* et *denken* n’ont pas la même préposition.","type":"trous","segments":["Die Schüler sprechen oft ",0," die Museen und denken ",1," das Programm."],"banque":["über","von","an","vor","auf"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**sich freuen auf** + accusatif : on se réjouit d’une chose **à venir** (la réjouissance du voyage)."},{"cle":{"type":"zone","ids":["m22"]},"explication":"**sich freuen über** + accusatif : on se réjouit d’une chose **présente ou passée** (la carte reçue)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**teilnehmen an** = participer à, **sich kümmern um** = s’occuper de, **abhängen von** = dépendre de, **bitten um** = demander (quelque chose à quelqu’un)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Fausses : *warten auf* (pas *für*), *sich interessieren für* (pas *an*), *Angst haben vor* (pas *auf*). Les trois autres respectent la rection."},{"cle":{"type":"trous","trous":[["uber"],["an"]]},"affichage":"über · an","explication":"**sprechen über** + acc. et **denken an** + acc. : *Sie sprechen über die Museen und denken an das Programm.*"}]$ex$::jsonb),
  ('3a430ec2-1f93-50b9-ba19-dd4cdf573202'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Da- et wo- : un tableau à compléter","competence":"manier-langue","situation":"Leyla a commencé le tableau des mots en da- et en wo-. Il lui manque deux cases.","documents":[{"id":"dawo","type":"tableau","titre":"Da- und wo-","colonnes":["Préposition","Reprise (une chose)","Question (une chose)"],"lignes":[["mit","damit","womit"],["für","dafür","?"],["auf","?","worauf"],["über","darüber","worüber"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche les trois formes déjà écrites où un r s’est intercalé.","aide":"Le r apparaît devant une préposition qui commence par une voyelle.","type":"zone","document":"dawo","multiple":true},{"enonce":"Complète les deux cases vides.","aide":"*auf* commence par une voyelle.","type":"trous","segments":["Reprise de auf : ",0," \nQuestion avec für : ",1],"banque":["wofür","darauf","woran","daauf"]},{"enonce":"Complète la réponse de Mia.","aide":"« Sport » est une chose, pas une personne.","type":"trous","segments":["Interessierst du dich für Sport? — Ja, ich interessiere mich ",0,"."],"banque":["darüber","dafür","damit","für ihn"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2","r3c1","r3c2"]},"explication":"**worauf, darüber, worüber** : *auf* et *über* commencent par une voyelle, donc on intercale un **r** entre *da-*/*wo-* et la préposition."},{"cle":{"type":"trous","trous":[["darauf"],["wofur"]]},"affichage":"darauf · wofür","explication":"**darauf** (da + r + auf) et **wofür** (wo + für : *f* est une consonne, pas de *r*)."},{"cle":{"type":"trous","trous":[["dafur"]]},"affichage":"dafür","explication":"**dafür** reprend « für Sport » : pour une chose, on remplace préposition + nom par *da-* + préposition."}]$ex$::jsonb),
  ('3a430ec2-1f93-50b9-ba19-dd4cdf573202'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Woran denkst du ? — Auf wen wartest du ?","competence":"comprendre-langue","situation":"Lisa et Hannes parlent des vacances. Dans leur conversation, certaines questions portent sur une chose, d’autres sur une personne.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Lisa","emoji":"👧","cote":"gauche"},{"nom":"Hannes","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lisa","texte":"Woran denkst du gerade?"},{"qui":"Hannes","texte":"An die Ferien! Ich freue mich so darauf."},{"qui":"Lisa","texte":"Ja, wir sprechen schon seit einer Stunde darüber."},{"qui":"Hannes","texte":"Ich warte noch auf jemanden."},{"qui":"Lisa","texte":"Auf wen wartest du?"},{"qui":"Hannes","texte":"Auf Tom. Er bringt die Karten."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui reprend « die Ferien » dans la phrase où Hannes dit qu’il s’en réjouit.","aide":"Le mot commence par *dar-*.","type":"zone","document":"sms","multiple":false},{"enonce":"Relie chaque phrase à ce qui la complète.","aide":"Une chose : *da-* ou *wo-*. Une personne : préposition + pronom.","type":"association","gauche":[{"id":"g0","texte":"Ich freue mich ___."},{"id":"g1","texte":"Wir sprechen seit einer Stunde ___."},{"id":"g2","texte":"___ denkst du gerade?"},{"id":"g3","texte":"___ wartest du? (une personne)"}],"droite":[{"id":"d0","texte":"Woran"},{"id":"d1","texte":"Auf wen"},{"id":"d2","texte":"darüber"},{"id":"d3","texte":"darauf"}]},{"enonce":"Touche le prénom qui répond à la question « Auf wen wartest du ? ».","aide":"Cherche une personne.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Hannes ne dit-il pas « Ich warte darauf » pour parler de Tom ?","aide":"Les formes en *da-* et *wo-* ne remplacent que des choses.","type":"choix","options":[{"id":"a","texte":"Parce que Tom est un prénom masculin et darauf féminin"},{"id":"b","texte":"Parce que warten n’a aucune préposition en allemand"},{"id":"c","texte":"Parce que darauf ne s’emploie qu’avec un mot neutre"},{"id":"d","texte":"Tom est une personne : on garde auf + pronom (auf ihn)"}],"multiple":false},{"enonce":"Complète la question.","aide":"« Les vacances » sont une chose.","type":"trous","segments":[0," sprechen Lisa und Hannes? — Über die Ferien."],"banque":["Wovon","Worüber","Über wen","Woran"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**darauf** reprend « auf die Ferien » : *sich freuen auf*, joie d’une chose à venir."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"**darauf**, **darüber** et **Woran** portent sur des choses ; **Auf wen** porte sur une personne."},{"cle":{"type":"zone","ids":["m30"]},"explication":"**Tom** est la personne attendue : on garde donc *auf* + pronom (*Auf wen ?*), sans forme en *wo-*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**da-** et **wo-** ne remplacent que des **choses** ou des idées. Pour une personne : *Ich warte auf ihn*, *Auf wen wartest du ?*"},{"cle":{"type":"trous","trous":[["woruber"]]},"affichage":"Worüber","explication":"**Worüber sprechen Lisa und Hannes ?** *sprechen über* + acc. : question sur une chose avec *wor-* + *über*."}]$ex$::jsonb),
  ('3a430ec2-1f93-50b9-ba19-dd4cdf573202'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre d’échange : annoncer un dass, un infinitif","competence":"manier-langue","situation":"Clara va passer l’été dans une famille allemande. Elle écrit à ses hôtes. Ses phrases emploient des mots en da- pour annoncer ce qui suit ; un tableau l’aide à poser des questions.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Ein Brief an die Gastfamilie","blocs":["Liebe Familie Roth,","ich freue mich sehr darauf, dass ich im Juli zu euch komme. Wir haben schon oft darüber gesprochen, was wir am Wochenende machen können.","Ich denke auch daran, meine Kamera mitzunehmen. Bis bald! Clara"],"source":"Lettre écrite pour l’exercice"},{"id":"fragen","type":"tableau","titre":"Fragen stellen","colonnes":["Verbe","Question sur une chose","Question sur une personne"],"lignes":[["warten","Worauf wartest du?","Auf wen wartest du?"],["denken","Woran denkst du?","?"],["sich interessieren","?","Für wen interessierst du dich?"],["sprechen","?","Über wen sprichst du?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot qui annonce la subordonnée introduite par dass.","aide":"Il suit « ich freue mich sehr ».","type":"zone","document":"brief","multiple":false},{"enonce":"Touche le mot qui annonce le groupe infinitif « meine Kamera mitzunehmen ».","aide":"Il suit « ich denke auch ».","type":"zone","document":"brief","multiple":false},{"enonce":"Dans « Wir haben oft darüber gesprochen, was wir am Wochenende machen können », que fait « darüber » ?","aide":"*sprechen über* garde sa préposition même devant une subordonnée.","type":"choix","options":[{"id":"a","texte":"Il remplace une personne, comme « sur elle »"},{"id":"b","texte":"Il remplace un lieu, comme « là-dessus »"},{"id":"c","texte":"Il annonce la subordonnée introduite par was"},{"id":"d","texte":"Il est facultatif et peut être supprimé"}],"multiple":false},{"enonce":"Complète les trois cases vides du tableau.","aide":"Chose : *wo(r)-* + préposition. Personne : préposition + *wen*.","type":"trous","segments":["Case 1 : ",0," interessierst du dich?\nCase 2 : ",1," denkst du? (une personne)\nCase 3 : ",2," sprichst du? (une chose)"],"banque":["An wen","Über wen","Für wen","Worüber","Wofür","Woran"]},{"enonce":"Quelle phrase est correcte ?","aide":"*warten* se construit avec *auf*.","type":"choix","options":[{"id":"a","texte":"Ich warte darauf, dass du kommst."},{"id":"b","texte":"Ich warte darüber, dass du kommst."},{"id":"c","texte":"Ich warte dafür, dass du kommst."},{"id":"d","texte":"Ich warte daran, dass du kommst."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**darauf** annonce la subordonnée en *dass* : *Ich freue mich darauf, dass ich im Juli komme.* Le français dit simplement « je me réjouis que… »."},{"cle":{"type":"zone","ids":["m30"]},"explication":"**daran** annonce l’infinitif : *Ich denke daran, meine Kamera mitzunehmen.* (*denken an*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**darüber** annonce la subordonnée *was wir … machen können* : l’allemand garde la trace de la préposition de *sprechen über*."},{"cle":{"type":"trous","trous":[["wofur"],["an wen"],["woruber"]]},"affichage":"Wofür · An wen · Worüber","explication":"**Wofür** (chose, *für* + consonne), **An wen** (personne), **Worüber** (chose, *über* commence par une voyelle : *wor-*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Ich warte darauf, dass du kommst.** *warten auf* : le pronom *darauf* annonce la subordonnée en *dass*."}]$ex$::jsonb),
  ('bd269c7c-0d90-57de-ae34-c341e21718e0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le suffixe donne l’article","competence":"manier-langue","situation":"Elias prépare une fiche : quand un nom allemand a un certain suffixe, on peut deviner son article sans le chercher. Lis sa fiche, puis applique-la à de nouveaux mots.","documents":[{"id":"suff","type":"tableau","titre":"Suffixe und Artikel","colonnes":["Suffixe","Article","Exemple"],"lignes":[["-ung","die","die Zeitung"],["-chen","das","das Mädchen"],["-ling","der","der Frühling"],["-heit","die","die Freiheit"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Devine l’article de ces trois mots grâce à leur suffixe.","aide":"Regarde la fin de chaque mot : -ung, -chen, -ling.","type":"trous","segments":[0," Wohnung, ",1," Hähnchen, ",2," Schmetterling"],"banque":["das","die","der"]},{"enonce":"Touche le suffixe qui rend neutre un nom, même quand il désigne une personne.","aide":"L’exemple de la ligne est une jeune fille.","type":"zone","document":"suff","multiple":false},{"enonce":"Range chaque mot dans la colonne de son article.","aide":"Cherche les suffixes -ling, -ist, -heit, -ung et -chen.","type":"categories","categories":[{"id":"c0","texte":"der"},{"id":"c1","texte":"die"},{"id":"c2","texte":"das"}],"items":[{"id":"i0","texte":"Journalist"},{"id":"i1","texte":"Gesundheit"},{"id":"i2","texte":"Häuschen"},{"id":"i3","texte":"Übung"},{"id":"i4","texte":"Lehrling"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["die"],["das"],["der"]]},"affichage":"die · das · der","explication":"**die Wohnung** (-ung), **das Hähnchen** (-chen), **der Schmetterling** (-ling) : le suffixe donne le genre à coup sûr."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"**-chen** rend tout neutre : *das Mädchen* (la jeune fille). Le genre suit le suffixe, pas le sexe."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c1","i4":"c0"}},"explication":"**der** Lehrling (-ling) et **der** Journalist (-ist) ; **die** Gesundheit (-heit) et **die** Übung (-ung) ; **das** Häuschen (-chen)."}]$ex$::jsonb),
  ('bd269c7c-0d90-57de-ae34-c341e21718e0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La semaine de la démocratie","competence":"analyser-texte","situation":"Le programme de la semaine de la démocratie est affiché au lycée de Mia. Chaque mot du programme a un genre que ses suffixes révèlent.","documents":[{"id":"prog","type":"texte","genre":"article","titre":"Woche der Demokratie","blocs":["Montag: Besuch von Journalist Max Brandt. Thema: Freiheit und Optimismus.","Dienstag: Universität Köln, Vortrag über Klima und Energie.","Mittwoch: Gespräch mit dem Direktor."],"source":"Programme écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot du programme qui est masculin grâce à son suffixe -ismus.","aide":"Il se trouve juste après « und », sur la ligne du lundi.","type":"zone","document":"prog","multiple":false},{"enonce":"Touche le mot du programme qui est féminin grâce à son suffixe -heit.","aide":"Il se trouve avant « und », sur la ligne du lundi.","type":"zone","document":"prog","multiple":true},{"enonce":"Range chaque mot dans la colonne de son article.","aide":"Pense aux familles de sens : météo, points cardinaux, jours, infinitifs, couleurs.","type":"categories","categories":[{"id":"c0","texte":"der"},{"id":"c1","texte":"die"},{"id":"c2","texte":"das"}],"items":[{"id":"i0","texte":"Regen"},{"id":"i1","texte":"Rot (la couleur)"},{"id":"i2","texte":"Essen (de essen, manger)"},{"id":"i3","texte":"Lampe"},{"id":"i4","texte":"Süden"},{"id":"i5","texte":"Montag"}]},{"enonce":"Devine l’article de ces trois mots.","aide":"Cherche les suffixes -ei, -um et -or.","type":"trous","segments":[0," Bäckerei, ",1," Museum, ",2," Motor"],"banque":["das","die","der"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**Optimismus** : le suffixe **-ismus** donne le masculin (*der Optimismus*)."},{"cle":{"type":"zone","ids":["m7","m11"]},"explication":"**Freiheit** : le suffixe **-heit** donne le féminin (*die Freiheit*)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c2","i3":"c1","i4":"c0","i5":"c0"}},"explication":"**der** Regen, Süden, Montag (météo, points cardinaux, jours) ; **die** Lampe (nom en -e) ; **das** Essen (infinitif devenu nom) et **das** Rot (couleur)."},{"cle":{"type":"trous","trous":[["die"],["das"],["der"]]},"affichage":"die · das · der","explication":"**die Bäckerei** (-ei), **das Museum** (-um), **der Motor** (-or) : chaque suffixe est un repère sûr."}]$ex$::jsonb),
  ('bd269c7c-0d90-57de-ae34-c341e21718e0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quand le début et la fin ne s’accordent pas","competence":"manier-langue","situation":"Léo hésite : beaucoup de noms en Ge- sont neutres, mais certains ont aussi un suffixe qui fait le féminin. Il a rassemblé deux tableaux : l’un sur les noms formés d’un verbe, l’autre sur les noms en Ge-.","documents":[{"id":"verb","type":"tableau","titre":"Vom Verb zum Nomen","colonnes":["Verbe","Nom formé","Article"],"lignes":[["leben","Leben","das"],["bauen","Bau","?"],["fortschreiten","Fortschritt","der"],["essen","Essen","?"],["springen","Sprung","?"]],"enteteLignes":true,"source":"Tableau d’après le cours"},{"id":"ge","type":"tableau","titre":"Wörter mit Ge-","colonnes":["Mot","Début","Fin"],"lignes":[["Gebäude","Ge-","-e"],["Gesundheit","Ge-","-heit"],["Gesellschaft","Ge-","-schaft"],["Gemüse","Ge-","-e"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Complète les articles des trois cases vides du premier tableau.","aide":"Un infinitif devenu nom est neutre ; un radical verbal devenu nom est masculin.","type":"trous","segments":["bauen → ",0," Bau\nessen → ",1," Essen\nspringen → ",2," Sprung"],"banque":["das","die","der"]},{"enonce":"Range chaque nom selon la façon dont il est formé.","aide":"Un infinitif ressemble au verbe entier, un radical est un verbe sans sa terminaison.","type":"categories","categories":[{"id":"c0","texte":"Infinitif devenu nom (neutre)"},{"id":"c1","texte":"Radical verbal devenu nom (masculin)"}],"items":[{"id":"i0","texte":"der Fortschritt"},{"id":"i1","texte":"der Bau"},{"id":"i2","texte":"das Essen"},{"id":"i3","texte":"der Sprung"},{"id":"i4","texte":"das Leben"}]},{"enonce":"Range chaque nom en Ge- dans la colonne de son article.","aide":"Regarde aussi la fin du mot : -heit et -schaft sont des suffixes très sûrs.","type":"categories","categories":[{"id":"c0","texte":"der"},{"id":"c1","texte":"die"},{"id":"c2","texte":"das"}],"items":[{"id":"i0","texte":"Gebäude"},{"id":"i1","texte":"Gesellschaft"},{"id":"i2","texte":"Gemüse"},{"id":"i3","texte":"Gesundheit"}]},{"enonce":"Pourquoi « Gesundheit » est-il féminin malgré son début Ge- ?","aide":"Regarde la colonne « Fin » du second tableau.","type":"choix","options":[{"id":"a","texte":"Parce que la santé est un mot de femme"},{"id":"b","texte":"Son suffixe -heit donne le féminin"},{"id":"c","texte":"Parce qu’il se termine par un -t"},{"id":"d","texte":"Parce que tous les mots abstraits sont féminins"}],"multiple":false},{"enonce":"Touche les deux terminaisons qui l’emportent sur le début Ge-.","aide":"Cherche les suffixes qui donnent le féminin.","type":"zone","document":"ge","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["der"],["das"],["der"]]},"affichage":"der · das · der","explication":"**der Bau** et **der Sprung** (radical verbal, masculin) ; **das Essen** (infinitif substantivé, neutre). *leben → das Leben* suit la même règle que *essen*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"La **conversion** (*leben → das Leben*, *essen → das Essen*) donne le neutre ; la **dérivation implicite** (*bauen → der Bau*, *springen → der Sprung*) donne le masculin."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c1"}},"explication":"**das** Gebäude et **das** Gemüse (Ge- l’emporte sur -e) ; **die** Gesundheit (-heit) et **die** Gesellschaft (-schaft) : le suffixe féminin est plus fort que le début Ge-."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le suffixe **-heit** est un repère très sûr : il donne *die*. Le début *Ge-* est plus faible que cette terminaison."},{"cle":{"type":"zone","ids":["r1c2","r2c2"]},"explication":"Les suffixes **-heit** et **-schaft** donnent le féminin, même si le mot commence par *Ge-*."}]$ex$::jsonb),
  ('d9ad30a6-3cab-5bfc-9fa9-314a9c56ff99'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un collègue, quatre cas","competence":"manier-langue","situation":"Zoé a recopié la déclinaison d’un masculin faible : der Kollege. Observe-la, puis utilise-la.","documents":[{"id":"dekl","type":"tableau","titre":"Der Kollege","colonnes":["Cas","Singulier","Pluriel"],"lignes":[["Nominatif","der Kollege","die Kollegen"],["Accusatif","den Kollegen","die Kollegen"],["Datif","dem Kollegen","den Kollegen"],["Génitif","des Kollegen","der Kollegen"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la seule forme du singulier qui ne se termine pas par -n.","aide":"C’est le cas où le nom est sujet de la phrase.","type":"zone","document":"dekl","multiple":false},{"enonce":"Touche les deux formes du datif.","aide":"Le datif suit des prépositions comme *mit* ou des verbes comme *helfen*.","type":"zone","document":"dekl","multiple":true},{"enonce":"Complète la phrase à l’accusatif.","aide":"*kennen* est suivi de l’accusatif, et un masculin faible prend -(e)n.","type":"trous","segments":["Ich kenne den ",0," von Max."],"banque":["Kollegen","Kollege","Kollegem","Kollegens"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Au **nominatif singulier**, le masculin faible garde sa forme de base : *der Kollege*. Partout ailleurs, il prend **-n**."},{"cle":{"type":"zone","ids":["r2c1","r2c2"]},"explication":"Au datif : **dem Kollegen** (singulier) et **den Kollegen** (pluriel). Les deux se terminent par *-n*."},{"cle":{"type":"trous","trous":[["kollegen"]]},"affichage":"Kollegen","explication":"**Ich kenne den Kollegen von Max.** À l’accusatif singulier, le masculin faible prend **-n** : *den Kollegen*."}]$ex$::jsonb),
  ('d9ad30a6-3cab-5bfc-9fa9-314a9c56ff99'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un policier français à Strasbourg","competence":"comprendre-langue","situation":"Tim vient d’arriver à Strasbourg. Il raconte à Eva comment il a trouvé son chemin. Observe comment se terminent les noms de personnes dans ses messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten aus Straßburg","participants":[{"nom":"Tim","emoji":"👦","cote":"gauche"},{"nom":"Eva","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tim","texte":"Ich bin gerade in Straßburg angekommen. Am Bahnhof habe ich einen Polizisten nach dem Weg gefragt."},{"qui":"Eva","texte":"Und? Hat er dir geholfen?"},{"qui":"Tim","texte":"Ja! Er ist Franzose, aber er spricht gut Deutsch. Er hat mir sogar mit meinem Koffer geholfen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le masculin faible qui est à l’accusatif et qui prend donc -en.","aide":"Tim a « posé une question à » quelqu’un : à quel cas est le complément ?","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le nom qui est au nominatif et qui n’a donc pas de -n.","aide":"Il est sujet de la phrase « Er ist … ».","type":"zone","document":"sms","multiple":false},{"enonce":"Relie chaque nominatif à son accusatif.","aide":"*der Herr* ne prend qu’un -n.","type":"association","gauche":[{"id":"g0","texte":"der Student"},{"id":"g1","texte":"der Franzose"},{"id":"g2","texte":"der Polizist"},{"id":"g3","texte":"der Herr"}],"droite":[{"id":"d0","texte":"den Studenten"},{"id":"d1","texte":"den Herrn"},{"id":"d2","texte":"den Franzosen"},{"id":"d3","texte":"den Polizisten"}]},{"enonce":"Complète la phrase au datif.","aide":"*schreiben* + datif de la personne : le masculin faible prend -en.","type":"trous","segments":["Wir schreiben dem ",0," (der Präsident) einen Brief."],"banque":["Präsidenten","Präsidents","Präsident","Präsidentem"]},{"enonce":"Pourquoi dit-on « Er ist Franzose » sans -n ?","aide":"Dans « Er ist Franzose », le mot est attribut du sujet.","type":"choix","options":[{"id":"a","texte":"Parce que Franzose est ici au pluriel"},{"id":"b","texte":"Parce que les nationalités n’ont jamais de -n"},{"id":"c","texte":"Parce que c’est le nominatif singulier, sans -en"},{"id":"d","texte":"Parce que le pronom er remplace le -n"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**einen Polizisten** : *fragen* est suivi de l’accusatif, et le masculin faible *der Polizist* prend **-en**."},{"cle":{"type":"zone","ids":["m24"]},"explication":"**Franzose** est au nominatif singulier : c’est la seule forme **sans -n** du masculin faible."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"À l’accusatif : **den Studenten, den Franzosen, den Polizisten** (avec -en), mais **den Herrn** (avec -n seulement)."},{"cle":{"type":"trous","trous":[["prasidenten"]]},"affichage":"Präsidenten","explication":"**Wir schreiben dem Präsidenten einen Brief.** Un masculin faible prend **-en** à tous les cas sauf au nominatif singulier."},{"cle":{"type":"choix","ids":["c"]},"explication":"Au **nominatif singulier**, le masculin faible n’a pas de -en : *der Franzose*. Il en prend partout ailleurs : *den Franzosen*, *dem Franzosen*."}]$ex$::jsonb),
  ('d9ad30a6-3cab-5bfc-9fa9-314a9c56ff99'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Herr, Herrn, Herren : l’exercice des pièges","competence":"manier-langue","situation":"Léa écrit au conseil de classe. Sa lettre contient des masculins faibles à différents cas, et un tableau lui rappelle quels noms en -e le sont vraiment.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Ein Brief an den Klassenrat","blocs":["Sehr geehrte Damen und Herren,","mein Name ist Lea Roth. Gestern habe ich den Präsidenten unserer Schülervertretung gesehen und mit Herrn Wolf gesprochen. Er ist ein sehr netter Mensch.","Mit freundlichen Grüßen, Lea Roth"],"source":"Lettre écrite pour l’exercice"},{"id":"fam","type":"tableau","titre":"Welche Nomen sind schwach?","colonnes":["Nom","Famille","Masculin faible ?"],"lignes":[["der Junge","être vivant en -e","oui"],["der Käse","chose en -e","?"],["der Name","nom abstrait en -e","?"],["der Journalist","origine étrangère en -ist","oui"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la forme de Herr qui prend -n au singulier.","aide":"Il y a aussi une forme au pluriel en tête de la lettre : ne la confonds pas.","type":"zone","document":"brief","multiple":false},{"enonce":"Touche le masculin faible qui est au nominatif et n’a donc pas de -en.","aide":"Il suit « Er ist ein sehr netter… ».","type":"zone","document":"brief","multiple":false},{"enonce":"Complète les deux cases vides du tableau avec le mot juste.","aide":"Une chose n’est pas un être vivant. Un nom abstrait en -e prend -n puis -ns au génitif.","type":"trous","segments":["der Käse : ",0,"\nder Name : ",1],"banque":["parfois","mixte","non","oui"]},{"enonce":"Range chaque phrase : est-elle correcte ou fausse ?","aide":"Un masculin faible prend -(en) partout sauf au nominatif singulier.","type":"categories","categories":[{"id":"c0","texte":"Correcte"},{"id":"c1","texte":"Fausse"}],"items":[{"id":"i0","texte":"Wir laden den Präsident ein."},{"id":"i1","texte":"Ich kenne den Namen des Journalisten."},{"id":"i2","texte":"Wir laden den Präsidenten ein."},{"id":"i3","texte":"Der Herr wartet."},{"id":"i4","texte":"Ich sehe den Herr."},{"id":"i5","texte":"Er hilft dem Nachbar."}]},{"enonce":"Pourquoi dit-on « des Namens » au génitif ?","aide":"Relis la ligne « der Name » du tableau.","type":"choix","options":[{"id":"a","texte":"Parce que le génitif prend toujours -s"},{"id":"b","texte":"Parce que Name est un nom neutre"},{"id":"c","texte":"Parce que Name est un masculin faible ordinaire"},{"id":"d","texte":"Les masculins mixtes prennent -ns au génitif"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**mit Herrn Wolf** : *der Herr* fait *dem/den Herrn* au singulier, mais *die Herren* au pluriel (*Damen und Herren*)."},{"cle":{"type":"zone","ids":["m28"]},"explication":"**Mensch** est au nominatif singulier : c’est la seule forme sans -en (*den Menschen*, *dem Menschen*…)."},{"cle":{"type":"trous","trous":[["non"],["mixte"]]},"affichage":"non · mixte","explication":"**der Käse : non** (une chose, *den Käse*). **der Name : mixte** (*den Namen, dem Namen, des Namens*)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"Fausses : *den Präsident* (→ *den Präsidenten*), *dem Nachbar* (→ *dem Nachbarn*), *den Herr* (→ *den Herrn*). Au nominatif, *Der Herr wartet* est juste."},{"cle":{"type":"choix","ids":["d"]},"explication":"*der Name* est un **masculin mixte** : -n à l’accusatif et au datif (*den, dem Namen*), mais **-ns** au génitif (*des Namens*). C’est aussi le cas de *der Glaube* ou *der Gedanke*."}]$ex$::jsonb),
  ('6a8f8b40-3154-5869-b6dd-c30cc135f510'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Où va le verbe ?","competence":"manier-langue","situation":"Pour son devoir, Sami a rangé trois outils de la cause et de la conséquence dans un tableau. Chacun impose sa place au verbe.","documents":[{"id":"outils","type":"tableau","titre":"Ursache und Folge","colonnes":["Outil","Nature","Place du verbe"],"lignes":[["weil","subordonnant","à la fin"],["denn","coordonnant","ordre normal : verbe en 2e position"],["deshalb","adverbe","inversion : verbe en 2e, sujet après"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la case qui dit où se place le verbe après weil.","aide":"Weil introduit une subordonnée.","type":"zone","document":"outils","multiple":false},{"enonce":"Complète la phrase avec le bon outil.","aide":"Regarde où est le verbe *ist* : à la fin de la subordonnée.","type":"trous","segments":["Lara geht nicht ins Kino, ",0," sie müde ist."],"banque":["weil","also","denn","deshalb"]},{"enonce":"Remets les mots dans l’ordre. Le premier groupe est « Lara bleibt zu Hause, ».","aide":"Après *weil*, le verbe va tout à la fin.","type":"ordre","items":[{"id":"a","texte":"sie"},{"id":"b","texte":"müde"},{"id":"c","texte":"ist"},{"id":"d","texte":"weil"},{"id":"e","texte":"Lara bleibt zu Hause,"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Après **weil**, le verbe conjugué part **à la fin** de la subordonnée : *… weil sie müde ist.*"},{"cle":{"type":"trous","trous":[["weil"]]},"affichage":"weil","explication":"**weil** : il rejette le verbe à la fin (*sie müde ist*). Avec *denn*, on aurait écrit *denn sie ist müde*."},{"cle":{"type":"ordre","ids":["e","d","a","b","c"]},"explication":"**Lara bleibt zu Hause, weil sie müde ist.** Dans la subordonnée en *weil*, le verbe conjugué est en dernière position."}]$ex$::jsonb),
  ('6a8f8b40-3154-5869-b6dd-c30cc135f510'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pourquoi Mia était-elle absente ?","competence":"comprendre-langue","situation":"Mia était absente et Paul lui écrit. Dans leur conversation, plusieurs mots expriment la cause ou la conséquence, chacun avec sa place pour le verbe.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Paul","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Paul","texte":"Warum warst du gestern nicht in der Schule?"},{"qui":"Mia","texte":"Ich war krank, deshalb bin ich zu Hause geblieben."},{"qui":"Paul","texte":"Da du krank warst, habe ich dir die Hefte mitgebracht."},{"qui":"Mia","texte":"Danke! Ich kann morgen vielleicht noch nicht kommen, denn ich habe noch Fieber."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe de conséquence qui provoque l’inversion du sujet et du verbe.","aide":"Après ce mot, « bin » passe avant « ich ».","type":"zone","document":"sms","multiple":false},{"enonce":"Touche la conjonction de coordination qui laisse le verbe à sa place normale.","aide":"Après ce mot, on lit « ich habe » dans l’ordre sujet puis verbe.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète la phrase avec le bon mot de conséquence.","aide":"Après le mot cherché, le verbe *fahre* vient avant *ich*.","type":"trous","segments":["Die Bahn streikt, ",0," fahre ich mit dem Rad."],"banque":["deshalb","denn","weil","da"]},{"enonce":"Relie chaque mot à la place du verbe qu’il impose.","aide":"Un subordonnant rejette le verbe, un adverbe provoque l’inversion.","type":"association","gauche":[{"id":"g0","texte":"weil"},{"id":"g1","texte":"denn"},{"id":"g2","texte":"deshalb"},{"id":"g3","texte":"da"}],"droite":[{"id":"d0","texte":"ordre normal"},{"id":"d1","texte":"cause connue, souvent en tête"},{"id":"d2","texte":"sujet après le verbe"},{"id":"d3","texte":"verbe à la fin"}]},{"enonce":"Pourquoi Paul commence-t-il sa phrase par « Da du krank warst » ?","aide":"Mia vient de dire qu’elle était malade.","type":"choix","options":[{"id":"a","texte":"Parce que da présente une cause déjà connue des deux"},{"id":"b","texte":"Parce que da est un adverbe de conséquence"},{"id":"c","texte":"Parce que da remplace deshalb"},{"id":"d","texte":"Parce que da s’emploie seulement avec denn"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**deshalb** : l’adverbe occupe la première place, donc le verbe est en 2e position et le sujet vient après : *deshalb bin ich …*."},{"cle":{"type":"zone","ids":["m35"]},"explication":"**denn** est une conjonction de coordination (position 0) : l’ordre reste normal, *denn ich habe noch Fieber*."},{"cle":{"type":"trous","trous":[["deshalb"]]},"affichage":"deshalb","explication":"**deshalb** : adverbe de conséquence, suivi du verbe puis du sujet (*deshalb fahre ich*). *weil*, *denn* et *da* expriment la cause."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**weil** → verbe final ; **denn** → ordre normal ; **deshalb** → inversion ; **da** → cause connue, souvent en début de phrase, verbe final."},{"cle":{"type":"choix","ids":["a"]},"explication":"**da** introduit une cause **déjà connue**, souvent en tête de phrase, et rejette le verbe à la fin : *Da du krank warst, …*."}]$ex$::jsonb),
  ('6a8f8b40-3154-5869-b6dd-c30cc135f510'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La fête de l’école sous la pluie","competence":"argumenter","situation":"Un journal d’élèves raconte l’annulation du Schulfest. Lis l’article et le tableau qui montre trois façons d’exprimer un même lien logique.","documents":[{"id":"fest","type":"texte","genre":"article","titre":"Das Fest fällt aus","blocs":["Am Samstag sollte das Schulfest stattfinden. Es regnete aber stark, sodass das Fest ausfiel. Die Schüler waren enttäuscht, denn sie hatten lange vorbereitet.","Wegen des Regens bleiben die Stände im Keller. Deshalb gibt es nächste Woche einen neuen Termin."],"source":"Article écrit pour l’exercice"},{"id":"drei","type":"tableau","titre":"Ein Lien, drei Konstruktionen","colonnes":["Construction","Phrase"],"lignes":[["adverbe","Es regnete, deshalb blieben wir drinnen."],["subordonnée","Wir blieben drinnen, weil es regnete."],["coordination","Wir blieben drinnen, denn es regnete."]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la préposition de cause, suivie du génitif, qui ouvre le deuxième paragraphe.","aide":"Elle se traduit par « à cause de ».","type":"zone","document":"fest","multiple":false},{"enonce":"Touche la phrase où le sujet passe derrière le verbe.","aide":"Cherche *blieben wir* au lieu de *wir blieben*.","type":"zone","document":"drei","multiple":false},{"enonce":"Remets les mots dans l’ordre pour exprimer la conséquence. Le premier groupe est « Es regnete stark, ».","aide":"*sodass* introduit une subordonnée : le verbe va à la fin.","type":"ordre","items":[{"id":"a","texte":"Es regnete stark,"},{"id":"b","texte":"ausfiel"},{"id":"c","texte":"sodass"},{"id":"d","texte":"das Spiel"}]},{"enonce":"Complète la phrase avec le mot qui annonce la conséquence.","aide":"La construction est *so + adjectif, dass*.","type":"trous","segments":["Das Essen war ",0," lecker, dass alle Kinder mehr wollten."],"banque":["ganz","so","zu","sehr"]},{"enonce":"Léa écrit « Es regnet, also nehme ich einen Schirm. » Un camarade traduit « also » par « aussi ». Que lui dis-tu ?","aide":"Dans la phrase, la pluie explique le parapluie.","type":"choix","options":[{"id":"a","texte":"Non : also veut dire « donc », « aussi » se dit auch"},{"id":"b","texte":"Oui : also exprime l’idée d’ajout, comme « et aussi »"},{"id":"c","texte":"Non : also veut dire « parce que » dans cette phrase"},{"id":"d","texte":"Oui : also est le mot allemand pour « aussi »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"**Wegen** + génitif : *wegen des Regens*. Ce n’est pas une conjonction : il n’y a pas de verbe à placer après elle."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"**Es regnete, deshalb blieben wir drinnen.** L’adverbe *deshalb* est en première place, donc l’inversion : verbe en 2e position, sujet après."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"**Es regnete stark, sodass das Spiel ausfiel.** *sodass* rejette le verbe conjugué en dernière position."},{"cle":{"type":"trous","trous":[["so"]]},"affichage":"so","explication":"**so … dass** exprime la conséquence : *Das Essen war so lecker, dass alle Kinder mehr wollten.*"},{"cle":{"type":"choix","ids":["a"]},"explication":"**also** signifie « donc » : il introduit la conséquence et provoque l’inversion (*also nehme ich*). « Aussi » se dit *auch*."}]$ex$::jsonb),
  ('16e9c918-98a3-5e99-a22f-d8e693511c64'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vélo et le parapluie de Mia","competence":"manier-langue","situation":"Mia raconte sa journée de samedi dans un petit journal de classe. Observe les petits mots devant les noms.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"Mia’s Saturday","blocs":["Mia bought a bike and an umbrella on Saturday.","The bike is red. The umbrella is yellow."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les articles qui présentent un objet pour la première fois.","aide":"Cherche les objets que Mia vient d’acheter : on ne les a pas encore mentionnés.","type":"zone","document":"journal","multiple":true},{"enonce":"Pourquoi écrit-on « The bike » dans le deuxième paragraphe ?","aide":"Compare avec la première phrase du texte.","type":"choix","options":[{"id":"a","texte":"Parce que le nom « bike » est ici employé au pluriel"},{"id":"b","texte":"Le vélo a déjà été cité : le lecteur sait de quel vélo on parle"},{"id":"c","texte":"Parce qu’il n’existe qu’un seul vélo dans le monde entier"},{"id":"d","texte":"Parce que « bike » commence par un son de consonne"}],"multiple":false},{"enonce":"Complète la première phrase du texte.","aide":"Prononce chaque mot : *bike* commence par un son de consonne, *umbrella* par un son de voyelle.","type":"trous","segments":["Mia bought ",0," bike and ",1," umbrella."],"banque":["a","the","some","an"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m5"]},"explication":"Les deux premiers articles, **a** bike et **an** umbrella, présentent des objets nouveaux : on emploie *a / an* pour un singulier dénombrable non identifié."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le vélo a été **déjà mentionné** : il est identifié, donc on emploie **the**."},{"cle":{"type":"trous","trous":[["a"],["an"]]},"affichage":"a · an","explication":"**a** bike (son de consonne) et **an** umbrella (son de voyelle) : c’est le son qui décide."}]$ex$::jsonb),
  ('16e9c918-98a3-5e99-a22f-d8e693511c64'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un SMS dans le train","competence":"manier-langue","situation":"Ana et Leo s’écrivent pendant que Leo voyage. Regarde quels noms n’ont aucun article, puis range les articles dans les bonnes cases.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Hi Leo! Are you on the 9.15 train?"},{"qui":"Leo","texte":"Yes! I’m reading books and drinking coffee. Life is easy on a train!"},{"qui":"Ana","texte":"Lucky you. I hate noise, and my seat is next to a baby."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les noms employés au sens général, sans article.","aide":"Ces noms ne sont ni précédés de a / an ni de the : on parle de la chose en général.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque phrase selon le mot qui manque dans le blanc.","aide":"Prononce le mot suivant : le son décide entre a et an. Un superlatif ou un objet unique appelle the.","type":"categories","categories":[{"id":"c0","texte":"a"},{"id":"c1","texte":"an"},{"id":"c2","texte":"the"},{"id":"c3","texte":"rien (Ø)"}],"items":[{"id":"i0","texte":"He is ___ European."},{"id":"i1","texte":"___ life is hard."},{"id":"i2","texte":"We waited ___ hour."},{"id":"i3","texte":"___ Moon is bright tonight."},{"id":"i4","texte":"I need ___ umbrella."},{"id":"i5","texte":"She is ___ best player."},{"id":"i6","texte":"___ dogs are loyal."}]},{"enonce":"Ana écrit « my seat is next to a baby ». Pourquoi « a » et non « the » ?","aide":"Ana n’a pas encore parlé de ce bébé avant cette phrase.","type":"choix","options":[{"id":"a","texte":"Parce que « baby » est un nom indénombrable"},{"id":"b","texte":"Parce qu’il n’y a qu’un seul bébé au monde"},{"id":"c","texte":"Parce qu’un superlatif suit toujours « a »"},{"id":"d","texte":"Ce bébé n’a pas encore été présenté au lecteur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m15","m16","m26"]},"explication":"**books, coffee, Life, noise** : pluriel ou indénombrable pris au sens général, on n’écrit rien (l’article zéro)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c3","i2":"c1","i3":"c2","i4":"c1","i5":"c2","i6":"c3"}},"explication":"**an** devant un son de voyelle (*umbrella*, *hour* : le h est muet) ; **a** devant *European* (son « you ») ; **the** devant l’objet unique (*Moon*) et le superlatif ; **rien** pour *life* et *dogs* pris au sens général."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est un bébé **non identifié** : on le présente avec **a** (singulier dénombrable, première mention)."}]$ex$::jsonb),
  ('16e9c918-98a3-5e99-a22f-d8e693511c64'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le mail plein de fautes","competence":"analyser-document","situation":"Sam écrit de Londres à son ami Tom, mais son mail contient des erreurs de déterminants. Corrige-le en t’aidant du tableau de la famille d’accueil.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Hi Tom!","blocs":["I’m writing from London. The life here is great! I live with an English family.","I have an university lesson every day, and I wait for a hour at the station when the train is late.","I walk along the Thames and I always say that the money is not everything."],"source":"Courriel écrit pour l’exercice"},{"id":"famille","type":"tableau","titre":"The host family","colonnes":["Possesseur","Objet possédé"],"lignes":[["Peter (un seul garçon)","car"],["les élèves (students)","bags"],["les enfants (children)","toys"],["Marie","brother"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre articles fautifs du courriel.","aide":"Deux sont des articles de sens général qu’il faut supprimer, deux ne respectent pas la règle du son.","type":"zone","document":"mail","multiple":true},{"enonce":"Corrige les deux articles qui suivent la règle du son.","aide":"Prononce *university* (« you-ni… ») et *hour* (« aoueur »).","type":"trous","segments":["I have ",0," university lesson and I wait for ",1," hour."],"banque":["some","a","the","an"]},{"enonce":"Comment corriger « The life here is great » ?","aide":"Sam parle de la vie en général, pas d’une vie précise.","type":"choix","options":[{"id":"a","texte":"The lives here are great"},{"id":"b","texte":"A life here is great"},{"id":"c","texte":"Life here is great"},{"id":"d","texte":"Lifes here are great"}],"multiple":false},{"enonce":"Relie chaque possesseur du tableau à la bonne forme.","aide":"Un pluriel en -s prend l’apostrophe seule ; un pluriel irrégulier prend ’s ; pour un possessif, le possesseur commande.","type":"association","gauche":[{"id":"g0","texte":"Peter"},{"id":"g1","texte":"les élèves"},{"id":"g2","texte":"les enfants"},{"id":"g3","texte":"Marie"}],"droite":[{"id":"d0","texte":"her brother"},{"id":"d1","texte":"the students’ bags"},{"id":"d2","texte":"Peter’s car"},{"id":"d3","texte":"the children’s toys"}]},{"enonce":"Remets les mots dans l’ordre pour dire « Les sacs des élèves sont ici ». Le premier mot est « The ».","aide":"Le possesseur passe devant l’objet possédé.","type":"ordre","items":[{"id":"a","texte":"are"},{"id":"b","texte":"The"},{"id":"c","texte":"students’"},{"id":"d","texte":"bags"},{"id":"e","texte":"here"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m17","m26","m46"]},"explication":"**The** life et **the** money : sens général, on n’écrit rien ; **an** university : on dit « you », donc *a* ; **a** hour : le h est muet, donc *an*."},{"cle":{"type":"trous","trous":[["a"],["an"]]},"affichage":"a · an","explication":"**a** university (son de consonne « you ») et **an** hour (h muet, son de voyelle)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Life here is great** : un indénombrable pris au sens général ne prend aucun article."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**Peter’s car** (singulier : ’s), **the students’ bags** (pluriel en -s : apostrophe seule), **the children’s toys** (pluriel irrégulier : ’s), **her brother** (c’est Marie, la possesseuse)."},{"cle":{"type":"ordre","ids":["b","c","d","a","e"]},"explication":"**The students’ bags are here.** Le génitif se lit à l’envers du français : *students’* avant *bags*."}]$ex$::jsonb),
  ('22239202-eacb-5f3f-a12a-9151dbae046c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le frigo de Zoé","competence":"lire-tableau","situation":"Zoé prépare un gâteau pour l’anniversaire de sa sœur. Elle a noté ce qu’il y a dans le frigo. La recette demande 5 eggs.","documents":[{"id":"frigo","type":"tableau","titre":"What’s in the fridge?","colonnes":["Item","Quantity"],"lignes":[["eggs","12"],["milk","2 bottles"],["apples","6"],["rice","1 kg"],["tomatoes","5"],["bread","1 loaf"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois aliments indénombrables (on ne peut pas dire « one milk, two milks »).","aide":"Un indénombrable se compte avec un intermédiaire : une bouteille, un kilo, une miche.","type":"zone","document":"frigo","multiple":true},{"enonce":"Complète avec many ou much.","aide":"*Milk* est indénombrable, *eggs* se compte.","type":"trous","segments":["How ",0," milk is there? And how ",1," eggs are there?"],"banque":["a little","a few","many","much"]},{"enonce":"La recette utilise 5 eggs. Combien d’eggs reste-t-il dans le frigo ?","aide":"Regarde la ligne « eggs » du tableau.","type":"nombre","unite":"eggs"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r3c0","r5c0"]},"explication":"**milk, rice, bread** sont indénombrables : on les compte avec *a bottle of*, *a kilo of*, *a loaf of*."},{"cle":{"type":"trous","trous":[["much"],["many"]]},"affichage":"much · many","explication":"How **much** milk (indénombrable) et how **many** eggs (dénombrable pluriel)."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 eggs","explication":"12 − 5 = **7 eggs**."}]$ex$::jsonb),
  ('22239202-eacb-5f3f-a12a-9151dbae046c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’affiche de la médiathèque","competence":"comprendre-langue","situation":"Jade lit l’affiche d’une médiathèque. Les petits mots de quantité y disent qui peut faire quoi, et ce qui manque.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Greenfield Library","sousTitre":"Welcome!","emoji":"📚","lignes":[{"texte":"Any student can join the library for free.","id":"z1"},{"texte":"You may borrow up to five books.","id":"z2"},{"texte":"Would you like some help? Ask our librarian.","id":"z3"},{"texte":"There aren’t any computers in the quiet room.","id":"z4"},{"texte":"Too many people? Come before 10 a.m.","id":"z5"}],"pied":"Open Monday to Saturday","teinte":"bleu","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui fait une proposition d’aide.","aide":"Une offre ou une demande se construit avec *some*.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui dit que n’importe quel élève peut s’inscrire.","aide":"Le mot cherché signifie « n’importe lequel » dans une phrase affirmative.","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète d’après l’affiche.","aide":"La phrase est négative.","type":"trous","segments":["There aren’t ",0," computers in the quiet room."],"banque":["some","any","much","a lot of"]},{"enonce":"Range chaque nom derrière le bon mot de quantité.","aide":"Peux-tu mettre un -s ou un chiffre devant ? Alors c’est dénombrable.","type":"categories","categories":[{"id":"c0","texte":"many"},{"id":"c1","texte":"much"}],"items":[{"id":"i0","texte":"books"},{"id":"i1","texte":"homework"},{"id":"i2","texte":"students"},{"id":"i3","texte":"people"},{"id":"i4","texte":"furniture"},{"id":"i5","texte":"advice"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La ligne **« Would you like some help? »** est une offre : on emploie *some* même dans une question."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**Any student can join** : dans une phrase affirmative, *any* signifie « n’importe quel »."},{"cle":{"type":"trous","trous":[["any"]]},"affichage":"any","explication":"Dans une phrase négative, on emploie **any** : *There aren’t any computers*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**many** devant les dénombrables pluriels (*people, books, students*) ; **much** devant les indénombrables (*homework, advice, furniture*)."}]$ex$::jsonb),
  ('22239202-eacb-5f3f-a12a-9151dbae046c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le voyage scolaire à Édimbourg","competence":"analyser-document","situation":"Le professeur écrit aux parents avant le voyage à Édimbourg. Lis sa lettre et le tableau de l’organisation, puis réponds comme un organisateur.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear parents","blocs":["Here is some information about our trip to Edinburgh. The news is good: the coach is free.","Please give your child one piece of advice: pack little luggage. Students must finish their homework before Friday."],"source":"Lettre écrite pour l’exercice"},{"id":"car","type":"tableau","titre":"The trip in numbers","colonnes":["Item","Number"],"lignes":[["Seats on the coach","50"],["Students","46"],["Teachers","3"],["Maximum pocket money (euros)","30"],["Mia’s pocket money (euros)","42"]],"enteteLignes":true,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les cinq noms indénombrables de la lettre.","aide":"Ils ne prennent jamais de -s et ne se placent pas derrière « a ».","type":"zone","document":"lettre","multiple":true},{"enonce":"Combien de places libres reste-t-il dans le car quand les élèves et les professeurs sont montés ?","aide":"Additionne d’abord les élèves et les professeurs.","type":"nombre","unite":"place"},{"enonce":"Complète avec le bon mot.","aide":"Le mot se place après l’adjectif.","type":"trous","segments":["The coach is big ",0," for 49 people."],"banque":["too","many","much","enough"]},{"enonce":"Mia a 42 euros, le maximum est 30. Quelle phrase est correcte ?","aide":"Compare 42 et 30, puis demande-toi si « money » est dénombrable.","type":"choix","options":[{"id":"a","texte":"She has too much pocket money"},{"id":"b","texte":"She has too many pocket money"},{"id":"c","texte":"She has enough pocket money"},{"id":"d","texte":"She has few pocket money"}],"multiple":false},{"enonce":"Remets les mots dans l’ordre. Le premier mot est « Please ».","aide":"Le verbe est suivi de la personne, puis de ce qu’on donne.","type":"ordre","items":[{"id":"a","texte":"me"},{"id":"b","texte":"advice"},{"id":"c","texte":"give"},{"id":"d","texte":"Please"},{"id":"e","texte":"some"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m10","m24","m27","m32"]},"explication":"**information, news, advice, luggage, homework** : ce sont des indénombrables ; *news* est singulier malgré son -s."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 place","explication":"46 + 3 = 49 personnes ; 50 − 49 = **1 place libre**."},{"cle":{"type":"trous","trous":[["enough"]]},"affichage":"enough","explication":"On dit **big enough** : *enough* se place après l’adjectif."},{"cle":{"type":"choix","ids":["a"]},"explication":"**too much** : *money* est indénombrable, et 42 dépasse 30."},{"cle":{"type":"ordre","ids":["d","c","a","e","b"]},"explication":"**Please give me some advice.** *Advice* est indénombrable : on utilise *some*, jamais « advices »."}]$ex$::jsonb),
  ('30842fd7-d8cb-57a5-abfc-923120a821d0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La chambre de Lily","competence":"comprendre-langue","situation":"Lily habite à Londres et décrit son immeuble, sa chambre et son humeur. Repère les adjectifs.","documents":[{"id":"lily","type":"texte","genre":"article","titre":"Lily’s world","blocs":["Lily lives in a tall building in London.","Her room is small but bright. She has a red sofa and old books. Today she looks happy."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche tous les adjectifs du texte.","aide":"Un adjectif décrit un nom ou suit un verbe comme *is* ou *looks*.","type":"zone","document":"lily","multiple":true},{"enonce":"Relie chaque adjectif à son sens.","aide":"Pense à l’immeuble, à la chambre, aux livres et à l’humeur de Lily.","type":"association","gauche":[{"id":"g0","texte":"tall"},{"id":"g1","texte":"small"},{"id":"g2","texte":"old"},{"id":"g3","texte":"happy"}],"droite":[{"id":"d0","texte":"vieux"},{"id":"d1","texte":"haut, grand"},{"id":"d2","texte":"heureux"},{"id":"d3","texte":"petit"}]},{"enonce":"Le texte dit « old books ». Pourquoi pas « olds books » ?","aide":"Regarde comment s’écrit « tall » devant le pluriel dans d’autres phrases.","type":"choix","options":[{"id":"a","texte":"Parce que le -s n’existe que devant une voyelle"},{"id":"b","texte":"Parce que « old » devrait être placé après le nom"},{"id":"c","texte":"Parce que « books » est un nom indénombrable"},{"id":"d","texte":"Un adjectif anglais ne prend jamais de -s"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m11","m13","m17","m20","m25"]},"explication":"Les six adjectifs sont **tall, small, bright, red, old, happy**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**tall** = haut, **small** = petit, **old** = vieux, **happy** = heureux."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’adjectif anglais est **invariable** : il ne s’accorde ni en genre ni en nombre."}]$ex$::jsonb),
  ('30842fd7-d8cb-57a5-abfc-923120a821d0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le stand de la brocante","competence":"manier-langue","situation":"Karim tient un stand à la brocante du village et décrit les objets en vente. Dans une annonce, les adjectifs se suivent dans un ordre précis.","documents":[{"id":"stand","type":"tableau","titre":"Stall list","colonnes":["Item","Opinion","Size","Age","Colour","Material"],"lignes":[["table","lovely","big","old","brown","wooden"],["bag","nice","small","new","black","leather"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"film","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Mina","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mina","texte":"The film was boring. I was so bored!"},{"qui":"Tim","texte":"Really? I was excited. The trailer looked amazing!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit dans quelle matière est fait le sac.","aide":"Cherche la ligne « bag », colonne « Material ».","type":"zone","document":"stand","multiple":false},{"enonce":"Écris l’annonce de la table dans le bon ordre. Le premier mot est « a ».","aide":"Opinion, taille, âge, couleur, matière : les colonnes du tableau suivent déjà cet ordre.","type":"ordre","items":[{"id":"a","texte":"big"},{"id":"b","texte":"lovely"},{"id":"c","texte":"a"},{"id":"d","texte":"brown"},{"id":"e","texte":"wooden"},{"id":"f","texte":"table"},{"id":"g","texte":"old"}]},{"enonce":"Quelle annonce du sac est écrite dans le bon ordre ?","aide":"Relis les colonnes du tableau de gauche à droite.","type":"choix","options":[{"id":"a","texte":"a nice small black new leather bag"},{"id":"b","texte":"a nice small new black leather bag"},{"id":"c","texte":"a small nice new black leather bag"},{"id":"d","texte":"a leather nice small new black bag"}],"multiple":false},{"enonce":"Touche l’adjectif en -ING qui décrit ce qui provoque l’ennui, puis celui qui décrit ce qui provoque l’émerveillement.","aide":"Un adjectif en -ING décrit la chose qui provoque l’émotion.","type":"zone","document":"film","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c5"]},"explication":"Le sac est en **leather** (cuir) : la matière se lit en dernière colonne."},{"cle":{"type":"ordre","ids":["c","b","a","g","d","e","f"]},"explication":"**a lovely big old brown wooden table** : opinion → taille → âge → couleur → matière → nom."},{"cle":{"type":"choix","ids":["b"]},"explication":"**a nice small new black leather bag** : opinion, taille, âge, couleur, matière."},{"cle":{"type":"zone","ids":["m3","m15"]},"explication":"**boring** (le film est ennuyeux) et **amazing** (la bande-annonce est impressionnante) décrivent ce qui provoque l’émotion ; *bored* et *excited* disent ce que les personnes ressentent."}]$ex$::jsonb),
  ('30842fd7-d8cb-57a5-abfc-923120a821d0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ceux qui fréquentent la bibliothèque de Millbrook","competence":"analyser-document","situation":"Dans la petite ville imaginaire de Millbrook, la bibliothèque a compté ses visiteurs en une semaine. Lis l’article et le graphique.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Millbrook Library","blocs":["In the small town of Millbrook, the poor are not invisible. The unemployed meet every Tuesday at the library.","The British visitors say they love the quiet rooms, and the young are getting busier every month."],"source":"Article imaginé pour l’exercice"},{"id":"visites","type":"graphique","forme":"barres-h","titre":"Visitors in one week","categories":["The young","The unemployed","The retired"],"series":[{"nom":"Visitors","valeurs":[65,40,25],"teinte":"turquoise"}],"axeY":{"titre":"Visitors","min":0,"max":80,"pas":10},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les adjectifs employés comme noms pour désigner un groupe de personnes (the poor, the unemployed…).","aide":"Ils sont précédés de *the* et le verbe qui les suit est au pluriel.","type":"zone","document":"article","multiple":true},{"enonce":"Touche la barre du groupe le plus nombreux.","aide":"Compare la longueur des trois barres.","type":"zone","document":"visites","multiple":false},{"enonce":"Combien de visiteurs en tout cette semaine-là ?","aide":"Additionne les trois groupes.","type":"nombre"},{"enonce":"Complète avec le bon verbe.","aide":"*The retired* désigne plusieurs personnes.","type":"trous","segments":["The retired ",0," the smallest group."],"banque":["be","am","are","is"]},{"enonce":"Relie chaque groupe à sa traduction.","aide":"Dans chaque cas, *the* + adjectif désigne tout un groupe.","type":"association","gauche":[{"id":"g0","texte":"the poor"},{"id":"g1","texte":"the unemployed"},{"id":"g2","texte":"the British"},{"id":"g3","texte":"the rich"}],"droite":[{"id":"d0","texte":"les pauvres"},{"id":"d1","texte":"les chômeurs"},{"id":"d2","texte":"les riches"},{"id":"d3","texte":"les Britanniques"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12","m20","m30"]},"explication":"**poor, unemployed, British, young** désignent des groupes entiers : *the* + adjectif, verbe au pluriel."},{"cle":{"type":"zone","ids":["k0"]},"explication":"**The young** ont la barre la plus longue : 65 visiteurs."},{"cle":{"type":"nombre","valeur":130,"tolerance":0},"affichage":"130","explication":"65 + 40 + 25 = **130 visiteurs**."},{"cle":{"type":"trous","trous":[["are"]]},"affichage":"are","explication":"**The retired are** : un adjectif substantivé désigne un groupe, donc le verbe est au pluriel."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**the poor** = les pauvres, **the unemployed** = les chômeurs, **the British** = les Britanniques, **the rich** = les riches."}]$ex$::jsonb),
  ('19027263-3518-5881-9d17-724736f5d69c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Froid, faim et grand-père de 90 ans","competence":"manier-langue","situation":"La famille de Mia rentre d’une longue promenade. Le papa raconte l’état de chacun. En français, on dit « avoir » ; en anglais, ce n’est pas le même verbe.","documents":[{"id":"famille","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Dad","emoji":"👨","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Dad","texte":"Quick, go inside! Mia is cold, Tom is hungry and Grandpa is ninety today!"},{"qui":"Mia","texte":"Don’t worry, Dad. I’ll make tea."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots que le français exprimerait avec le verbe « avoir » (avoir froid, avoir faim, avoir 90 ans).","aide":"Cherche les mots qui décrivent l’état ou l’âge d’une personne.","type":"zone","document":"famille","multiple":true},{"enonce":"Complète la phrase de Dad.","aide":"Quel verbe sert à dire l’état en anglais ?","type":"trous","segments":["Tom ",0," hungry."],"banque":["have","does","has","is"]},{"enonce":"Comment dit-on « Grand-père a 90 ans » ?","aide":"Pour l’âge, l’anglais emploie *be* et ne dit pas « years ».","type":"choix","options":[{"id":"a","texte":"Grandpa has 90 years"},{"id":"b","texte":"Grandpa does 90"},{"id":"c","texte":"Grandpa is 90"},{"id":"d","texte":"Grandpa have 90 ans"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m8","m12"]},"explication":"**cold, hungry, ninety** : l’anglais dit *be cold*, *be hungry*, *be ninety*, là où le français dit « avoir »."},{"cle":{"type":"trous","trous":[["is"]]},"affichage":"is","explication":"On emploie **is** : *Tom is hungry* (« Tom a faim »)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Grandpa is 90** : l’âge se dit avec *be*, jamais avec *have*."}]$ex$::jsonb),
  ('19027263-3518-5881-9d17-724736f5d69c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le déjeuner de Max","competence":"comprendre-langue","situation":"Lena et Max discutent de leur matinée. Observe comment l’auxiliaire *do* travaille dans leur conversation.","documents":[{"id":"cafe","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Lena","emoji":"👩","cote":"gauche"},{"nom":"Max","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Did you have lunch at school, Max?"},{"qui":"Max","texte":"No, I didn’t. But I DO like a big dinner!"},{"qui":"Lena","texte":"So do I!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux auxiliaires qui construisent la question et la négation au prétérit.","aide":"Le prétérit de *do* sert à poser une question et à nier.","type":"zone","document":"cafe","multiple":true},{"enonce":"Touche l’auxiliaire qui sert à insister (« si, j’aime vraiment »).","aide":"Il est écrit en majuscules dans la réponse de Max.","type":"zone","document":"cafe","multiple":false},{"enonce":"Dans « So do I », que fait Lena ?","aide":"Que dit-on quand on est d’accord avec quelqu’un ?","type":"choix","options":[{"id":"a","texte":"Elle pose une question sur le dîner de Max"},{"id":"b","texte":"Elle nie ce que Max vient d’affirmer"},{"id":"c","texte":"Elle reprend l’auxiliaire de Max pour dire « moi aussi »"},{"id":"d","texte":"Elle insiste sur le verbe de sa propre phrase"}],"multiple":false},{"enonce":"Complète la négation avec le verbe qui convient.","aide":"Après *didn’t*, le verbe reste à la base verbale.","type":"trous","segments":["I didn’t ",0," lunch at school."],"banque":["has","have","having","had"]},{"enonce":"Remets les mots dans l’ordre pour poser la question. Le premier mot est « Did ».","aide":"Auxiliaire, sujet, verbe : l’auxiliaire passe devant le sujet.","type":"ordre","items":[{"id":"a","texte":"breakfast"},{"id":"b","texte":"have"},{"id":"c","texte":"Did"},{"id":"d","texte":"today"},{"id":"e","texte":"you"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m9"]},"explication":"**Did** (question) et **didn’t** (négation) : l’auxiliaire *do* porte la marque du temps et de la forme."},{"cle":{"type":"zone","ids":["m12"]},"explication":"**DO** à l’affirmative sert à insister ou à contredire : *I DO like a big dinner*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**So do I** = « moi aussi » : l’anglais reprend l’auxiliaire de la phrase précédente."},{"cle":{"type":"trous","trous":[["have"]]},"affichage":"have","explication":"**I didn’t have lunch** : c’est *didn’t* qui porte le prétérit, donc *have* reste à la base."},{"cle":{"type":"ordre","ids":["c","e","b","a","d"]},"explication":"**Did you have breakfast today?** : auxiliaire, sujet, verbe à la base, complément."}]$ex$::jsonb),
  ('19027263-3518-5881-9d17-724736f5d69c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le club de cuisine","competence":"analyser-texte","situation":"Le journal du lycée a publié les notes du club de cuisine. Lucie y cherche les auxiliaires. Aide-toi aussi du tableau des trois verbes.","documents":[{"id":"club","type":"texte","genre":"article","titre":"Cooking club notes","blocs":["Tom is cooking pasta. Lucy has a big pan.","She does her homework before the club, but she didn’t have breakfast. The pasta was cooked in ten minutes.","Have you finished? Does Lucy like pasta? Tom says: “I like pasta.”"],"source":"Texte écrit pour l’exercice"},{"id":"roles","type":"tableau","titre":"Three verbs, two jobs","colonnes":["Verbe","Comme auxiliaire","Comme verbe lexical"],"lignes":[["BE","forme en -ING, passif","être"],["HAVE","temps composés","avoir, posséder ; prendre (have breakfast)"],["DO","négation et question aux temps simples","faire"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Dans chaque phrase du texte, le verbe en gras est…","aide":"Un auxiliaire aide un autre verbe ; un verbe lexical porte le sens à lui seul.","type":"categories","categories":[{"id":"c0","texte":"auxiliaire"},{"id":"c1","texte":"verbe lexical"}],"items":[{"id":"i0","texte":"The pasta **was** cooked in ten minutes."},{"id":"i1","texte":"She **didn’t** have breakfast."},{"id":"i2","texte":"**Have** you finished?"},{"id":"i3","texte":"Lucy **has** a big pan."},{"id":"i4","texte":"Tom **is** cooking pasta."},{"id":"i5","texte":"She **does** her homework."}]},{"enonce":"Touche la case qui dit à quoi sert DO comme auxiliaire.","aide":"Cherche la ligne DO, colonne « Comme auxiliaire ».","type":"zone","document":"roles","multiple":false},{"enonce":"Pourquoi écrit-on « She didn’t have breakfast » et non « She hadn’t breakfast » ?","aide":"Regarde la ligne HAVE du tableau : que veut dire *have breakfast* ?","type":"choix","options":[{"id":"a","texte":"Parce que « breakfast » est un nom indénombrable en anglais"},{"id":"b","texte":"Ici have est lexical (prendre) : la négation passe par do"},{"id":"c","texte":"Parce que « have » ne se met jamais au passé simple"},{"id":"d","texte":"Parce que la forme « hadn’t » n’existe pas en anglais"}],"multiple":false},{"enonce":"Tom dit « I like pasta ». Lucy aussi aime les pâtes. Que répond-elle ?","aide":"Reprends l’auxiliaire de la phrase de Tom : il n’y en a pas, donc l’anglais en fabrique un.","type":"choix","options":[{"id":"a","texte":"So have I"},{"id":"b","texte":"So am I"},{"id":"c","texte":"So do I"},{"id":"d","texte":"So like I"}],"multiple":false},{"enonce":"Remets les mots dans l’ordre pour poser la question. Le premier mot est « Does ».","aide":"Auxiliaire, sujet, verbe lexical à la base, puis complément.","type":"ordre","items":[{"id":"a","texte":"Lucy"},{"id":"b","texte":"have"},{"id":"c","texte":"big"},{"id":"d","texte":"pan"},{"id":"e","texte":"a"},{"id":"f","texte":"Does"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"**is** cooking (forme en -ING), **didn’t**, **was** cooked (passif) et **Have** you finished (temps composé) sont des auxiliaires ; **has** (posséder) et **does** (faire) sont lexicaux."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**DO** auxiliaire sert à la négation et à la question aux temps simples (*Does Lucy like pasta?*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"*Have breakfast* = « prendre le petit-déjeuner » : **have** est lexical, donc la négation se fait avec **didn’t**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**So do I** : *like* est lexical, on reprend avec l’auxiliaire fabriqué *do*."},{"cle":{"type":"ordre","ids":["f","a","b","e","c","d"]},"explication":"**Does Lucy have a big pan?** : *does* porte le -s de la 3e personne, donc *have* reste à la base."}]$ex$::jsonb),
  ('700b1a90-893e-520a-8a66-331797e06f8c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les règles de la piscine","competence":"comprendre-langue","situation":"Samir arrive à la piscine municipale et lit le panneau à l’entrée. Chaque ligne dit ce qu’on doit, ne peut pas ou n’a pas besoin de faire.","documents":[{"id":"panneau","type":"fiche","modele":"panneau","entete":"Riverside Swimming Pool","sousTitre":"Rules","emoji":"⚠️","lignes":[{"texte":"You must shower before you swim.","id":"z1"},{"texte":"You mustn’t run near the pool.","id":"z2"},{"texte":"You can use the lockers for free.","id":"z3"},{"texte":"You don’t have to bring a towel: we have some.","id":"z4"}],"pied":"Thank you!","teinte":"bleu","source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui exprime une interdiction.","aide":"Cherche la forme négative du modal de l’obligation.","type":"zone","document":"panneau","multiple":false},{"enonce":"Touche la ligne qui dit que ce n’est pas la peine : ce n’est pas obligatoire.","aide":"Elle emploie *have to*, pas *must*.","type":"zone","document":"panneau","multiple":false},{"enonce":"Complète avec le bon modal.","aide":"La phrase dit que c’est interdit.","type":"trous","segments":["You ",0," run near the pool: it is forbidden."],"banque":["mustn’t","can","may","must"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**You mustn’t run** : *mustn’t* exprime l’interdiction (« il ne faut pas »)."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**You don’t have to bring a towel** : *don’t have to* exprime l’absence d’obligation."},{"cle":{"type":"trous","trous":[["mustn t"]]},"affichage":"mustn’t","explication":"On écrit **mustn’t** : c’est l’interdiction."}]$ex$::jsonb),
  ('700b1a90-893e-520a-8a66-331797e06f8c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui a pris le sandwich ?","competence":"raisonner","situation":"Emma a perdu son sandwich dans la salle commune. Jake, Tom et Lisa étaient dans les parages. Lis leur discussion et suis le raisonnement.","documents":[{"id":"enquete","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Jake","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"My sandwich has gone! It must have been Lisa: she was in the room."},{"qui":"Jake","texte":"Well, it can’t have been Tom: he was at the gym."},{"qui":"Jake","texte":"It might have been the dog. You should have closed the door!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui exprime une déduction presque certaine.","aide":"Emma est sûre d’elle : elle déduit le coupable.","type":"zone","document":"enquete","multiple":false},{"enonce":"Relie chaque structure à ce qu’elle exprime.","aide":"Chaque structure porte un regard sur le passé.","type":"association","gauche":[{"id":"g0","texte":"must have + participe"},{"id":"g1","texte":"should have + participe"},{"id":"g2","texte":"might have + participe"},{"id":"g3","texte":"can’t have + participe"}],"droite":[{"id":"d0","texte":"reproche ou regret"},{"id":"d1","texte":"déduction quasi certaine"},{"id":"d2","texte":"déduction négative"},{"id":"d3","texte":"hypothèse possible"}]},{"enonce":"Complète pour faire un reproche à Emma.","aide":"Un reproche sur le passé se dit avec le modal du conseil.","type":"trous","segments":["You ",0," have closed the door!"],"banque":["can’t","should","might","must"]},{"enonce":"Pourquoi Jake exclut-il Tom ?","aide":"Relis la réponse de Jake sur Tom.","type":"choix","options":[{"id":"a","texte":"Tom a déjà été puni plusieurs fois pour cela"},{"id":"b","texte":"Tom était au gym : il ne peut pas l’avoir pris"},{"id":"c","texte":"Tom n’aime pas du tout les sandwichs à la dinde"},{"id":"d","texte":"Tom devait rester dans la pièce à côté ce jour-là"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**must have been Lisa** : *must have* + participe passé exprime une déduction quasi certaine."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**must have** = déduction, **should have** = reproche, **might have** = hypothèse, **can’t have** = déduction négative."},{"cle":{"type":"trous","trous":[["should"]]},"affichage":"should","explication":"**should have closed** : *should have* + participe passé exprime un reproche."},{"cle":{"type":"choix","ids":["b"]},"explication":"**It can’t have been Tom** : Tom était au gym, donc c’est impossible."}]$ex$::jsonb),
  ('700b1a90-893e-520a-8a66-331797e06f8c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le camp d’été de Ruth","competence":"analyser-document","situation":"Ruth écrit à l’organisateur d’un camp. Compare son message avec le règlement affiché.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Dear Mr Hall","blocs":["I’m afraid I can’t come on Saturday: I have to work on Saturdays. My brother might come instead.","He can swim very well. Next year, he will be able to join the older group."],"source":"Courriel écrit pour l’exercice"},{"id":"regles","type":"fiche","modele":"panneau","entete":"Camp Sunshine","sousTitre":"Rules","emoji":"⚠️","lignes":[{"texte":"You must wear a helmet."},{"texte":"You mustn’t touch the fire."},{"texte":"You don’t have to bring food."},{"texte":"You mustn’t leave the camp alone."},{"texte":"You don’t have to sing at the party."},{"texte":"You must tell the guide."}],"pied":"Have fun!","teinte":"jaune","source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui exprime la capacité.","aide":"Il parle de ce que le frère sait faire.","type":"zone","document":"mail","multiple":false},{"enonce":"Ruth écrit « I have to work on Saturdays ». Pourquoi pas « I must work » ?","aide":"Qui décide qu’elle doit travailler : elle ou sa situation ?","type":"choix","options":[{"id":"a","texte":"Parce que « must » ne se met jamais à la première personne"},{"id":"b","texte":"Parce que « work » est un verbe à particule"},{"id":"c","texte":"Parce que « have to » exprime une déduction"},{"id":"d","texte":"L’obligation vient des circonstances (son travail), pas de sa décision"}],"multiple":false},{"enonce":"Complète la phrase de Ruth.","aide":"Deux modaux ne se suivent pas : on emprunte une autre forme.","type":"trous","segments":["Next year, he will ",0," able to join the older group."],"banque":["be","is","can","have"]},{"enonce":"Range les phrases du règlement.","aide":"Ne confonds pas « il ne faut pas » et « ce n’est pas la peine ».","type":"categories","categories":[{"id":"c0","texte":"obligation (must)"},{"id":"c1","texte":"interdiction (mustn’t)"},{"id":"c2","texte":"pas obligé (don’t have to)"}],"items":[{"id":"i0","texte":"You must wear a helmet."},{"id":"i1","texte":"You mustn’t touch the fire."},{"id":"i2","texte":"You mustn’t leave the camp alone."},{"id":"i3","texte":"You don’t have to bring food."},{"id":"i4","texte":"You must tell the guide."},{"id":"i5","texte":"You don’t have to sing at the party."}]}]}$ex$::jsonb,
