   $ex${"titre":"Ne lâche rien, Jules !","competence":"comprendre-langue","situation":"Jules s’entraîne pour une course avec son coach. Les verbes qu’ils emploient changent de sens selon la particule.","documents":[{"id":"course","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Coach","emoji":"🏃","cote":"gauche"},{"nom":"Jules","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Coach","texte":"Don’t give up, Jules! You’re almost there."},{"qui":"Jules","texte":"I’m looking for my bottle. Could you look after my bag?"},{"qui":"Coach","texte":"Sure. Turn on the music and keep going!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots du verbe à particule qui veut dire « abandonner ».","aide":"Le coach l’emploie pour encourager Jules.","type":"zone","document":"course","multiple":true},{"enonce":"Relie chaque verbe à son sens.","aide":"Retrouve chaque verbe dans la conversation.","type":"association","gauche":[{"id":"g0","texte":"give up"},{"id":"g1","texte":"look for"},{"id":"g2","texte":"look after"},{"id":"g3","texte":"turn on"}],"droite":[{"id":"d0","texte":"chercher"},{"id":"d1","texte":"garder, s’occuper de"},{"id":"d2","texte":"allumer"},{"id":"d3","texte":"abandonner"}]},{"enonce":"Comment dit-on « Allume-la ! » à propos de la musique ?","aide":"Dans un verbe à particule, le pronom s’intercale.","type":"choix","options":[{"id":"a","texte":"Turn it on!"},{"id":"b","texte":"Turn on it!"},{"id":"c","texte":"On it turn!"},{"id":"d","texte":"It turn on!"}],"multiple":false}]}$ex$::jsonb,
