   $ex${"titre":"Le voyage reporté","competence":"analyser-document","situation":"Sam et Eli préparent un voyage en train. Lis le courriel de Sam et regarde les horaires.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Hi Eli","blocs":["We had to put the trip off until Sunday. I look forward to seeing you then.","Could you look up the train times? Which train are you waiting for?"],"source":"Courriel écrit pour l’exercice"},{"id":"trains","type":"tableau","titre":"Train times","colonnes":["Train","Leaves","Arrives"],"lignes":[["A","09:15","11:40"],["B","10:05","12:30"]],"enteteLignes":true,"source":"Horaires inventés pour l’exercice"}],"questions":[{"enonce":"Combien de minutes dure le trajet du train A ?","aide":"Passe de 09:15 à 11:40 : compte d’abord les heures, puis les minutes.","type":"nombre","unite":"minutes"},{"enonce":"Touche la préposition laissée à la fin de la question.","aide":"Le verbe est *wait* ; la préposition qui le suit est restée tout à la fin.","type":"zone","document":"mail","multiple":false},{"enonce":"Quelle phrase est correcte ?","aide":"Pour un verbe à particule, le pronom s’intercale.","type":"choix","options":[{"id":"a","texte":"Let’s off put it"},{"id":"b","texte":"Let’s put on off it"},{"id":"c","texte":"Let’s put off it"},{"id":"d","texte":"Let’s put it off"}],"multiple":false},{"enonce":"Pourquoi Sam écrit-il « I look forward to seeing you » et non « to see » ?","aide":"Remplace « seeing you » par « the weekend » : « to » reste-t-il le même ?","type":"choix","options":[{"id":"a","texte":"Parce que « seeing » est un adjectif"},{"id":"b","texte":"Parce qu’il y a déjà un infinitif dans la phrase"},{"id":"c","texte":"« to » est ici une préposition : il faut un gérondif après"},{"id":"d","texte":"Parce que « look forward » ne se construit jamais avec un verbe"}],"multiple":false},{"enonce":"Relie chaque verbe à son sens.","aide":"Tous les verbes commencent par *look*, c’est la suite qui change le sens.","type":"association","gauche":[{"id":"g0","texte":"look into"},{"id":"g1","texte":"look up"},{"id":"g2","texte":"look after"},{"id":"g3","texte":"look forward to"}],"droite":[{"id":"d0","texte":"s’occuper de"},{"id":"d1","texte":"chercher dans une liste"},{"id":"d2","texte":"attendre avec impatience"},{"id":"d3","texte":"enquêter sur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":145,"tolerance":0},"affichage":"145 minutes","explication":"De 09:15 à 11:40 : 2 h 25, soit 120 + 25 = **145 minutes**."},{"cle":{"type":"zone","ids":["m28"]},"explication":"**for** : en anglais courant, la préposition d’un verbe prépositionnel reste en fin de phrase."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Let’s put it off** : le pronom se place entre le verbe et la particule."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans **look forward to**, *to* est une préposition : le verbe qui suit prend la forme en -ING."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"**look into** = enquêter, **look up** = chercher dans une liste ou un dictionnaire, **look after** = s’occuper de, **look forward to** = attendre avec impatience."}]$ex$::jsonb),
