  ('b5079322-7f73-59e2-a08b-fb74fa97080d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le carnet du camp de Chloé","competence":"analyser-document","situation":"Mia écrit à son correspondant Alex, et le camp d’été où ils se retrouvent tient un carnet de bord. Lis les deux documents.","documents":[{"id":"mia","type":"texte","genre":"lettre","titre":"Dear Alex","blocs":["I look forward to meeting you in July. I’m interested in learning French and I’m good at singing.","Please don’t leave without saying goodbye!"],"source":"Courriel écrit pour l’exercice"},{"id":"carnet","type":"tableau","titre":"Camp diary","colonnes":["Day","What happened"],"lignes":[["Monday","Ana remembered to take her sunscreen."],["Tuesday","Ben tried climbing the wall: it was fun."],["Wednesday","Chloe stopped to rest on the path."]],"enteteLignes":true,"source":"Carnet écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre verbes en -ING placés après une préposition.","aide":"Regarde ce qui précède chaque verbe : *to* (préposition), *in*, *at*, *without*.","type":"zone","document":"mia","multiple":true},{"enonce":"Complète le début du courriel.","aide":"Dans *look forward to*, *to* est une préposition.","type":"trous","segments":["I look forward to ",0," you in July."],"banque":["met","to meet","meeting","meet"]},{"enonce":"Range chaque verbe selon la forme qui le suit.","aide":"Révise les deux listes du cours.","type":"categories","categories":[{"id":"c0","texte":"+ -ING"},{"id":"c1","texte":"+ to + verbe"}],"items":[{"id":"i0","texte":"manage"},{"id":"i1","texte":"practise"},{"id":"i2","texte":"keep"},{"id":"i3","texte":"refuse"},{"id":"i4","texte":"mind"},{"id":"i5","texte":"promise"}]},{"enonce":"Que s’est-il passé mardi au camp ?","aide":"*Try* + -ING = essayer pour voir.","type":"choix","options":[{"id":"a","texte":"Ben a arrêté de grimper"},{"id":"b","texte":"Ben s’est efforcé de grimper sans y arriver"},{"id":"c","texte":"Ben a oublié de grimper"},{"id":"d","texte":"Ben a essayé de grimper pour voir ce que ça donnait"}],"multiple":false},{"enonce":"Touche la case où Chloé s’arrête pour se reposer (et non d’arrêter de se reposer).","aide":"Cherche *stop* suivi de *to*.","type":"zone","document":"carnet","multiple":false}]}$ex$::jsonb,
