  ('fb2f1865-37c7-547f-83c3-77e39ae3badd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La routine de Sara","competence":"comprendre-langue","situation":"Sara décrit sa routine dans un petit portrait pour le journal du lycée. Observe où se placent les adverbes.","documents":[{"id":"sara","type":"texte","genre":"article","titre":"Sara’s routine","blocs":["Sara often works late. She is always happy and she never skips breakfast.","She speaks English fluently."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois adverbes de fréquence.","aide":"Ils répondent à la question « combien de fois ? ».","type":"zone","document":"sara","multiple":true},{"enonce":"Remets les mots dans l’ordre. Le premier mot est « Sara ».","aide":"L’adverbe de fréquence se place avant le verbe lexical.","type":"ordre","items":[{"id":"a","texte":"Sara"},{"id":"b","texte":"late"},{"id":"c","texte":"works"},{"id":"d","texte":"often"}]},{"enonce":"Où se place l’adverbe de manière « fluently » dans la dernière phrase ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Après le complément : She speaks English fluently"},{"id":"b","texte":"Tout au début, avant le sujet de la phrase"},{"id":"c","texte":"Entre le verbe et son complément d’objet"},{"id":"d","texte":"Avant le verbe, juste après le sujet du verbe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m6","m10"]},"explication":"**often, always, never** sont des adverbes de fréquence."},{"cle":{"type":"ordre","ids":["a","d","c","b"]},"explication":"**Sara often works late.** : *often* se place avant le verbe lexical."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’adverbe de manière se place **après le verbe ou après son complément**, jamais entre le verbe et son COD."}]$ex$::jsonb),
  ('fb2f1865-37c7-547f-83c3-77e39ae3badd'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un appel difficile","competence":"manier-langue","situation":"Jo et Eli se parlent au téléphone. Plusieurs adverbes en -ly ou sans -ly ont un sens qui surprend.","documents":[{"id":"appel","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Jo","emoji":"👧","cote":"gauche"},{"nom":"Eli","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jo","texte":"Sorry, I could hardly hear you."},{"qui":"Eli","texte":"I’m terribly sorry! I was speaking quietly because the baby is asleep."},{"qui":"Jo","texte":"No problem. I haven’t seen Tom lately. Is he OK?"},{"qui":"Eli","texte":"He is, but he drives too fast and his car is nearly dead."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe qui veut dire « à peine ».","aide":"Ne pense pas à « durement ».","type":"zone","document":"appel","multiple":false},{"enonce":"Relie chaque adverbe à son sens.","aide":"Trois de ces adverbes sont des faux amis.","type":"association","gauche":[{"id":"g0","texte":"hardly"},{"id":"g1","texte":"lately"},{"id":"g2","texte":"nearly"},{"id":"g3","texte":"terribly"}],"droite":[{"id":"d0","texte":"presque"},{"id":"d1","texte":"récemment"},{"id":"d2","texte":"terriblement"},{"id":"d3","texte":"à peine"}]},{"enonce":"Touche l’adverbe qui a la même forme que l’adjectif.","aide":"Il n’a pas de -ly.","type":"zone","document":"appel","multiple":false},{"enonce":"Complète avec l’adverbe formé sur l’adjectif quiet.","aide":"Pour un verbe, il faut un adverbe.","type":"trous","segments":["Eli was speaking ",0,"."],"banque":["quietly","quite","quieter","quiet"]},{"enonce":"Quelle phrase est correcte ?","aide":"N’insère jamais l’adverbe entre le verbe et son COD.","type":"choix","options":[{"id":"a","texte":"She speaks English fluently"},{"id":"b","texte":"She speaks English very fluent"},{"id":"c","texte":"She speaks fluently English"},{"id":"d","texte":"Fluently she English speaks"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**hardly** signifie « à peine », pas « durement » : c’est un faux ami."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"**hardly** = à peine, **lately** = récemment, **nearly** = presque, **terribly** = terriblement."},{"cle":{"type":"zone","ids":["m34"]},"explication":"**fast** est à la fois adjectif et adverbe : *a fast car*, *he drives fast*."},{"cle":{"type":"trous","trous":[["quietly"]]},"affichage":"quietly","explication":"**quietly** : on forme l’adverbe en ajoutant *-ly* à l’adjectif."},{"cle":{"type":"choix","ids":["a"]},"explication":"**She speaks English fluently.** : l’adverbe de manière suit le complément."}]$ex$::jsonb),
  ('fb2f1865-37c7-547f-83c3-77e39ae3badd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les avis sur l’hôtel Seaview","competence":"analyser-document","situation":"Un hôtel côtier imaginaire a demandé l’avis de ses clients. Lis un commentaire et le graphique des notes de deux années.","documents":[{"id":"avis","type":"texte","genre":"article","titre":"Review of the Seaview Hotel","blocs":["Unfortunately, the room was small. The staff were extremely kind and the breakfast was ready at 8.","We have never eaten so well. The food was much better than last year. We could hardly leave!"],"source":"Avis imaginé pour l’exercice"},{"id":"notes","type":"graphique","forme":"barres","titre":"Guests’ ratings (out of 10)","categories":["Room","Food","Staff"],"series":[{"nom":"2023","valeurs":[6,5,8],"teinte":"bleu"},{"nom":"2024","valeurs":[6,8,9],"teinte":"ambre"}],"axeY":{"titre":"Rating","min":0,"max":10,"pas":2},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe de phrase qui commente toute la première phrase.","aide":"Il est en tête, suivi d’une virgule.","type":"zone","document":"avis","multiple":false},{"enonce":"Touche l’adverbe de fréquence placé entre have et le participe passé.","aide":"Il se trouve après l’auxiliaire.","type":"zone","document":"avis","multiple":false},{"enonce":"Touche la catégorie dont la note a le plus progressé entre 2023 et 2024.","aide":"Calcule la différence pour chaque catégorie.","type":"zone","document":"notes","multiple":false},{"enonce":"Complète la phrase d’après le commentaire.","aide":"Devant un comparatif, on n’emploie pas *very*.","type":"trous","segments":["The food was ",0," better in 2024."],"banque":["hardly","very","nearly","much"]},{"enonce":"Quelle phrase décrit correctement le personnel ?","aide":"L’adverbe de fréquence se place après *be*.","type":"choix","options":[{"id":"a","texte":"The staff are always kind"},{"id":"b","texte":"The staff always are kind"},{"id":"c","texte":"Always the staff kind are"},{"id":"d","texte":"The staff kind are always"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"**Unfortunately** commente l’ensemble de la phrase : c’est un adverbe de phrase."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**never** se place après l’auxiliaire *have* : *We have never eaten*."},{"cle":{"type":"zone","ids":["k1"]},"explication":"**Food** passe de 5 à 8 (+ 3), alors que la chambre ne bouge pas et le personnel gagne un point."},{"cle":{"type":"trous","trous":[["much"]]},"affichage":"much","explication":"**much better** : devant un comparatif, on emploie *much* ou *far*, jamais *very*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**The staff are always kind.** : l’adverbe de fréquence suit le verbe *be*."}]$ex$::jsonb),
  ('7b28d6ef-5f30-5b50-a1e4-50ce3f17773d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Que fait Lena en ce moment ?","competence":"comprendre-langue","situation":"Les parents de Lena se demandent ce qu’elle fait. Entre ce qu’elle fait d’habitude et ce qu’elle fait maintenant, l’anglais n’emploie pas le même présent.","documents":[{"id":"parents","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"What is Lena doing?"},{"qui":"Dad","texte":"She is working in her room now. She usually goes to the gym on Fridays."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que l’action se passe en ce moment.","aide":"Il signifie « maintenant ».","type":"zone","document":"parents","multiple":false},{"enonce":"Touche le mot qui montre une habitude.","aide":"Il se place avant le verbe et revient chaque semaine.","type":"zone","document":"parents","multiple":false},{"enonce":"Complète la phrase de Dad.","aide":"C’est une habitude, à la 3e personne du singulier.","type":"trous","segments":["She ",0," to the gym every Friday."],"banque":["is going","gos","goes","go"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**now** indique une action en cours : on emploie BE + -ING."},{"cle":{"type":"zone","ids":["m12"]},"explication":"**usually** annonce une habitude : on emploie le présent simple."},{"cle":{"type":"trous","trous":[["goes"]]},"affichage":"goes","explication":"**goes** : présent simple, avec le -s de la 3e personne."}]$ex$::jsonb),
  ('7b28d6ef-5f30-5b50-a1e4-50ce3f17773d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Toujours en train de se plaindre","competence":"manier-langue","situation":"Mia et Tom parlent du bruit dans leur immeuble. Les formes verbales de leurs messages ne disent pas toutes la même chose.","documents":[{"id":"immeuble","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Listen! The baby is crying again."},{"qui":"Tom","texte":"Is your neighbour at home? He is always complaining about the noise!"},{"qui":"Mia","texte":"I’m thinking about moving. I know a nice flat. It belongs to my uncle."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe en -ING qui exprime l’agacement de Tom.","aide":"Il suit *always*.","type":"zone","document":"immeuble","multiple":false},{"enonce":"Touche les deux verbes d’état qui ne se mettent pas en -ING.","aide":"Un verbe de connaissance et un verbe de possession.","type":"zone","document":"immeuble","multiple":true},{"enonce":"« I’m thinking about moving » et « I think it’s good » ont-ils le même sens de *think* ?","aide":"Pense à la forme en -ING : est-ce un état ou une action en cours ?","type":"choix","options":[{"id":"a","texte":"Oui : les deux expriment une activité mentale"},{"id":"b","texte":"Non : l’un est un souvenir, l’autre une habitude"},{"id":"c","texte":"Oui : les deux expriment une opinion"},{"id":"d","texte":"Non : l’un est une activité mentale, l’autre une opinion"}],"multiple":false},{"enonce":"Complète avec le bon temps.","aide":"Après *when*, on emploie le présent pour parler du futur.","type":"trous","segments":["When Tom ",0,", I will call you."],"banque":["will arrive","arrives","is arriving","arrive"]},{"enonce":"« We’re leaving tomorrow » exprime…","aide":"Regarde le mot *tomorrow*.","type":"choix","options":[{"id":"a","texte":"Une vérité générale"},{"id":"b","texte":"Une habitude du matin"},{"id":"c","texte":"Une action en cours en ce moment"},{"id":"d","texte":"Un futur programmé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**He is always complaining** : *always* + BE + -ING exprime l’agacement."},{"cle":{"type":"zone","ids":["m23","m28"]},"explication":"**know** et **belongs** sont des verbes d’état : *I am knowing* est impossible."},{"cle":{"type":"choix","ids":["d"]},"explication":"**I’m thinking about** = réfléchir à ; **I think it’s good** = être d’avis que."},{"cle":{"type":"trous","trous":[["arrives"]]},"affichage":"arrives","explication":"**arrives** : après *when*, l’anglais emploie le présent là où le français dit le futur."},{"cle":{"type":"choix","ids":["d"]},"explication":"BE + -ING avec un repère futur exprime un **futur programmé**."}]$ex$::jsonb),
  ('7b28d6ef-5f30-5b50-a1e4-50ce3f17773d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La traversée vers Calais","competence":"analyser-document","situation":"Noa prépare un voyage en ferry et écrit à son cousin. Regarde aussi le tableau des verbes dont le sens change avec la forme.","documents":[{"id":"noa","type":"texte","genre":"lettre","titre":"Hi Luc","blocs":["We’re leaving for Calais tomorrow. The ferry usually leaves at 9.30.","My cousin is waiting for us at the port right now. I know he is tired. When we arrive in Calais, we will call you."],"source":"Courriel écrit pour l’exercice"},{"id":"verbes","type":"tableau","titre":"Verbs that change meaning","colonnes":["Verb","Présent simple","BE + -ING"],"lignes":[["think","opinion","activité mentale"],["have","posséder","prendre (un repas)"],["see","comprendre","rencontrer"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque phrase du courriel.","aide":"Cherche les repères de temps : *tomorrow*, *usually*, *right now*.","type":"categories","categories":[{"id":"c0","texte":"présent simple (habitude)"},{"id":"c1","texte":"BE + -ING (en cours)"},{"id":"c2","texte":"BE + -ING (futur programmé)"}],"items":[{"id":"i0","texte":"My cousin is waiting for us right now."},{"id":"i1","texte":"We’re leaving for Calais tomorrow."},{"id":"i2","texte":"The ferry usually leaves at 9.30."}]},{"enonce":"Touche le verbe d’état qui ne peut pas se mettre en -ING.","aide":"Il exprime une connaissance.","type":"zone","document":"noa","multiple":false},{"enonce":"Complète la dernière phrase.","aide":"Après *when*, on emploie le présent.","type":"trous","segments":["When we ",0," in Calais, we will call you."],"banque":["will arrive","arrived","are arriving","arrive"]},{"enonce":"Touche la case qui donne le sens de *have* dans « I’m having lunch ».","aide":"Cherche la ligne HAVE, colonne BE + -ING.","type":"zone","document":"verbes","multiple":false},{"enonce":"« I’m seeing my cousin tomorrow » signifie…","aide":"Regarde la ligne SEE, colonne BE + -ING.","type":"choix","options":[{"id":"a","texte":"Je comprends mon cousin demain"},{"id":"b","texte":"Je rencontre mon cousin demain"},{"id":"c","texte":"Je regarde mon cousin demain"},{"id":"d","texte":"Je possède mon cousin demain"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0"}},"explication":"**usually leaves** = habitude (présent simple) ; **is waiting right now** = en cours ; **We’re leaving tomorrow** = futur programmé."},{"cle":{"type":"zone","ids":["m24"]},"explication":"**know** est un verbe d’état : on dit *I know*, jamais *I am knowing*."},{"cle":{"type":"trous","trous":[["arrive"]]},"affichage":"arrive","explication":"**arrive** : après *when*, le présent simple remplace le futur."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"**prendre (un repas)** : *have* en -ING ne signifie plus posséder."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec BE + -ING, **see** signifie « rencontrer » et la phrase exprime un futur programmé."}]$ex$::jsonb),
  ('43fa045e-6cfe-5709-a514-fc92b7648b60'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La vie de Granny Rose","competence":"se-reperer-temps","situation":"Pour le livret de la famille, Léa a tracé la frise de la vie de sa grand-mère, imaginée pour l’exercice. Observe-la.","documents":[{"id":"frise","type":"frise","titre":"Granny Rose’s life","debut":1950,"fin":2020,"pas":10,"periodes":[{"id":"z1","debut":1990,"fin":2015,"nom":"The bakery years","teinte":"ambre"}],"evenements":[{"id":"z2","date":1950,"nom":"Born in Leeds"},{"id":"z3","date":1968,"nom":"Moved to London"},{"id":"z4","date":1975,"nom":"Got married"},{"id":"z5","date":1990,"nom":"Opened a bakery"},{"id":"z6","date":2015,"nom":"Retired"}],"source":"Frise imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui s’est passé en 1968.","aide":"Regarde la graduation entre 1960 et 1970.","type":"zone","document":"frise","multiple":false},{"enonce":"Quel âge avait-elle quand elle a ouvert la boulangerie ?","aide":"Soustrais l’année de sa naissance.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase.","aide":"Un fait daté appelle le prétérit du verbe être.","type":"trous","segments":["She ",0," born in 1950."],"banque":["was","is","did","were"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"En **1968**, Granny Rose *moved to London* : un fait daté, donc le prétérit."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 ans","explication":"1990 − 1950 = **40 ans**."},{"cle":{"type":"trous","trous":[["was"]]},"affichage":"was","explication":"**was** : « elle est née en 1950 », prétérit de *be*."}]$ex$::jsonb),
  ('43fa045e-6cfe-5709-a514-fc92b7648b60'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pourquoi tu n’as pas répondu ?","competence":"manier-langue","situation":"Ana veut savoir pourquoi Ben n’a pas répondu à son appel hier. Observe les deux prétérits de la discussion.","documents":[{"id":"appel","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Why didn’t you answer the phone yesterday?"},{"qui":"Ben","texte":"I was watching a film when you called. Then I went out."},{"qui":"Ana","texte":"Did you see the match last night?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui décrit le décor, l’action en cours.","aide":"Il suit *was*.","type":"zone","document":"appel","multiple":false},{"enonce":"Touche le verbe qui décrit l’événement qui interrompt le décor.","aide":"C’est le verbe qui suit *when*.","type":"zone","document":"appel","multiple":false},{"enonce":"Relie chaque verbe à son prétérit.","aide":"Trois de ces prétérits sont irréguliers.","type":"association","gauche":[{"id":"g0","texte":"go"},{"id":"g1","texte":"see"},{"id":"g2","texte":"take"},{"id":"g3","texte":"study"}],"droite":[{"id":"d0","texte":"went"},{"id":"d1","texte":"took"},{"id":"d2","texte":"saw"},{"id":"d3","texte":"studied"}]},{"enonce":"Complète la négation.","aide":"Après *didn’t*, le verbe reste à la base.","type":"trous","segments":["I didn’t ",0," to school yesterday."],"banque":["went","gone","go","going"]},{"enonce":"Ben a vu le match hier soir. Quelle phrase est correcte ?","aide":"Un repère de temps passé comme *last night* appelle le prétérit.","type":"choix","options":[{"id":"a","texte":"I saw the match last night"},{"id":"b","texte":"I was see the match last night"},{"id":"c","texte":"I have seen the match last night"},{"id":"d","texte":"I did saw the match last night"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**was watching** : le prétérit en BE + -ING décrit l’action en cours, comme l’imparfait."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**called** : le prétérit simple exprime l’événement qui arrive."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**go → went**, **see → saw**, **take → took** sont irréguliers ; **study → studied** est régulier (y → ied)."},{"cle":{"type":"trous","trous":[["go"]]},"affichage":"go","explication":"**go** : *didn’t* porte la marque du passé, le verbe revient à la base."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I saw the match last night.** : un fait daté ne se met jamais au present perfect."}]$ex$::jsonb),
  ('43fa045e-6cfe-5709-a514-fc92b7648b60'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Alarme au musée","competence":"analyser-document","situation":"Un soir, l’alarme a retenti dans un musée imaginaire. Un agent d’entretien raconte ce qu’il faisait, et le registre de sécurité donne les heures.","documents":[{"id":"temoin","type":"texte","genre":"article","titre":"Mr Hill’s statement","blocs":["Last Friday, I was cleaning the main hall when the alarm rang. I didn’t see anybody, but two guards were talking in the corridor.","The police arrived soon afterwards."],"source":"Témoignage écrit pour l’exercice"},{"id":"registre","type":"tableau","titre":"Security log","colonnes":["Time","Event"],"lignes":[["20:00","The guard started his round"],["20:30","The alarm rang"],["20:45","The police arrived"],["21:30","The museum closed"]],"enteteLignes":true,"source":"Registre inventé pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui décrit ce que faisait Mr Hill, le décor de la scène.","aide":"Il suit *was* et se termine par -ing.","type":"zone","document":"temoin","multiple":false},{"enonce":"Touche la case qui donne l’heure à laquelle l’alarme a sonné.","aide":"Cherche la ligne « The alarm rang ».","type":"zone","document":"registre","multiple":false},{"enonce":"Combien de minutes se sont écoulées entre l’alarme et l’arrivée de la police ?","aide":"Lis les heures dans le registre.","type":"nombre","unite":"minutes"},{"enonce":"Range chaque verbe du témoignage selon sa forme.","aide":"Un événement qui arrive est au prétérit simple ; une action en cours est en BE + -ING.","type":"categories","categories":[{"id":"c0","texte":"prétérit simple (événement)"},{"id":"c1","texte":"prétérit BE + -ING (décor)"}],"items":[{"id":"i0","texte":"were talking"},{"id":"i1","texte":"arrived"},{"id":"i2","texte":"rang"},{"id":"i3","texte":"didn’t see"},{"id":"i4","texte":"was cleaning"}]},{"enonce":"Mr Hill écrit « the police arrived soon afterwards ». Quelle phrase est incorrecte ?","aide":"Un fait daté ne se met pas au present perfect.","type":"choix","options":[{"id":"a","texte":"The police arrived at 20:45"},{"id":"b","texte":"The police arrived soon afterwards"},{"id":"c","texte":"The police have arrived at 20:45"},{"id":"d","texte":"The police didn’t arrive at 20:30"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**was cleaning** : le prétérit en BE + -ING décrit l’action en cours au moment où l’alarme sonne."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"L’alarme a sonné à **20:30**."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 minutes","explication":"20:45 − 20:30 = **15 minutes**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1"}},"explication":"**rang, arrived, didn’t see** sont des événements ; **was cleaning, were talking** sont le décor, des actions en cours."},{"cle":{"type":"choix","ids":["c"]},"explication":"**The police have arrived at 20:45** est faux : avec une heure précise, on emploie le **prétérit**."}]$ex$::jsonb),
  ('64a8db89-cb61-53a7-8b47-610efa443328'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Nora est enfin à l’aéroport","competence":"comprendre-langue","situation":"Nora voyage seule pour la première fois et écrit à son ami Sam depuis l’aéroport. Repère les mots qui accompagnent le present perfect.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Nora","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nora","texte":"I have just arrived at the airport."},{"qui":"Sam","texte":"Have you ever flown alone before?"},{"qui":"Nora","texte":"No, I have never flown alone. I haven’t found my gate yet."},{"qui":"Sam","texte":"You have already passed security, so look at the screen!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les cinq petits mots qui accompagnent souvent le present perfect (just, ever…).","aide":"Ils disent « à l’instant », « un jour dans ma vie », « jamais », « pas encore », « déjà ».","type":"zone","document":"sms","multiple":true},{"enonce":"Relie chaque mot du dialogue à son sens.","aide":"Relis la phrase de Nora ou de Sam où apparaît chaque mot.","type":"association","gauche":[{"id":"g0","texte":"just"},{"id":"g1","texte":"never"},{"id":"g2","texte":"already"},{"id":"g3","texte":"yet (dans « haven’t … yet »)"}],"droite":[{"id":"d0","texte":"déjà"},{"id":"d1","texte":"à l’instant"},{"id":"d2","texte":"jamais"},{"id":"d3","texte":"pas encore"}]},{"enonce":"Complète la phrase de Nora.","aide":"Le sujet est à la troisième personne du singulier.","type":"trous","segments":["Nora ",0," just arrived at the airport."],"banque":["have","is","do","has"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m9","m16","m24","m27"]},"explication":"Les cinq marqueurs sont **just, ever, never, yet, already**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**just** = à l’instant, **never** = jamais, **already** = déjà, **yet** avec une négation = pas encore."},{"cle":{"type":"trous","trous":[["has"]]},"affichage":"has","explication":"Au present perfect on emploie **has** avec *Nora* (she) : *Nora has just arrived*."}]$ex$::jsonb),
  ('64a8db89-cb61-53a7-8b47-610efa443328'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les passions de Leo, depuis quand ?","competence":"manier-langue","situation":"Nous sommes en 2025. Leo, un lycéen de Bristol, présente trois activités et l’année où il les a commencées.","documents":[{"id":"fiche","type":"tableau","titre":"Leo’s activities","colonnes":["Activity","Started in"],"lignes":[["live in Bristol",2018],["play the guitar",2021],["learn Welsh",2024]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne le point de départ de la guitare.","aide":"Cherche la ligne « play the guitar », puis la colonne « Started in ».","type":"zone","document":"fiche","multiple":false},{"enonce":"Depuis combien d’années Leo joue-t-il de la guitare ? (Nous sommes en 2025.)","aide":"Soustrais l’année de départ à l’année actuelle.","type":"nombre","unite":"ans"},{"enonce":"Complète avec for ou since.","aide":"Une durée (four years) et un point de départ (2018) n’appellent pas le même mot.","type":"trous","segments":["Leo has played the guitar ",0," four years and has lived in Bristol ",1," 2018."],"banque":["ago","for","during","since"]},{"enonce":"Quelle phrase sur l’apprentissage du gallois est correcte ?","aide":"Ce qui a commencé dans le passé et dure encore se dit au present perfect.","type":"choix","options":[{"id":"a","texte":"He has learnt Welsh for 2024."},{"id":"b","texte":"He learns Welsh since 2024."},{"id":"c","texte":"He learnt Welsh since 2024."},{"id":"d","texte":"He has learnt Welsh since 2024."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Leo joue de la guitare depuis **2021** : un point de départ appelle *since*."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"2025 − 2021 = **4 ans** : on dira *for four years*."},{"cle":{"type":"trous","trous":[["for"],["since"]]},"affichage":"for · since","explication":"**for** + durée (*four years*), **since** + point de départ (*2018*)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**He has learnt Welsh since 2024** : present perfect, car l’action continue, et *since* devant une année."}]$ex$::jsonb),
  ('64a8db89-cb61-53a7-8b47-610efa443328'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La cuisine d’Ella, encore toute bleue","competence":"analyser-document","situation":"Ella repeint sa cuisine. Elle envoie un courriel à sa cousine, et son plan des murs indique où en sont les travaux.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Ella’s email","blocs":["Hi Cathy,","My hands are blue! I’ve been painting since eight o’clock. I’ve painted two walls and I’ve been waiting for the third one to dry for an hour."],"source":"Courriel écrit pour l’exercice"},{"id":"murs","type":"tableau","titre":"The kitchen walls","colonnes":["Wall","Status"],"lignes":[["North","finished"],["East","finished"],["South","drying"],["West","not started"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes en -ING qui insistent sur la durée de l’activité.","aide":"Ils suivent « I’ve been ».","type":"zone","document":"mail","multiple":true},{"enonce":"Combien de murs Ella a-t-elle terminés d’après le plan ?","aide":"Compte les lignes « finished ».","type":"nombre"},{"enonce":"Quel mur Ella attend-elle ? Touche son nom dans le plan.","aide":"Elle attend « the third one to dry » : cherche l’état « drying ».","type":"zone","document":"murs","multiple":false},{"enonce":"Pourquoi Ella écrit-elle « I’ve been painting » et non « I’ve painted » pour sa matinée ?","aide":"Pense aux mains bleues : que montrent-elles ?","type":"choix","options":[{"id":"a","texte":"Elle insiste sur la durée de l’activité et ses traces (mains bleues)"},{"id":"b","texte":"Le present perfect simple est impossible avec une heure de départ"},{"id":"c","texte":"L’action est terminée et ne laisse aucune trace visible"},{"id":"d","texte":"Le mot painting est un nom et non un verbe conjugué"}],"multiple":false},{"enonce":"Complète la phrase de la cousine.","aide":"La structure est have + been + -ING.","type":"trous","segments":["You ",0," ",1," crying: your eyes are red."],"banque":["being","been","have","has"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m19"]},"explication":"Ce sont **painting** et **waiting** : *been* + -ING insiste sur la durée. *Painted* donne le résultat."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Le plan indique **2** murs terminés, ce qui correspond à « I’ve painted two walls »."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"C’est le mur **South** : il est en train de sécher."},{"cle":{"type":"choix","ids":["a"]},"explication":"**BE + -ING** met en avant la **durée** et ses **traces** visibles (les mains bleues)."},{"cle":{"type":"trous","trous":[["have"],["been"]]},"affichage":"have · been","explication":"**You have been crying** : present perfect en BE + -ING, car on voit les traces (yeux rouges)."}]$ex$::jsonb),
  ('4f60614a-1aca-5bbc-8509-05a30eda89a3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le train de Tom est déjà parti","competence":"comprendre-langue","situation":"Tom arrive à la gare : quel dommage ! Lis son histoire et repère ce qui s’est passé avant.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"A bad morning","blocs":["When Tom arrived at the station, the train had already left. He had overslept and he had missed the early one too.","Then he bought a ticket for the next train."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois participes passés qui suivent « had ».","aide":"Le prétérit « arrived » et « bought » ne suivent pas had.","type":"zone","document":"recit","multiple":true},{"enonce":"Range ces trois faits dans l’ordre où ils se sont passés.","aide":"Le past perfect marque ce qui s’est passé en premier.","type":"ordre","items":[{"id":"a","texte":"Tom bought a ticket"},{"id":"b","texte":"Tom arrived at the station"},{"id":"c","texte":"The train left"}]},{"enonce":"Complète la phrase.","aide":"Le film a commencé avant notre arrivée.","type":"trous","segments":["When we got home, the film ",0," already started."],"banque":["has","had","have","did"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m13","m17"]},"explication":"Les participes sont **left, overslept, missed** : had + participe passé = past perfect."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"Le train était **déjà parti** (past perfect) quand Tom est arrivé (prétérit), puis il a acheté son billet."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** + participe : le film avait déjà commencé avant l’arrivée (prétérit *got*)."}]$ex$::jsonb),
  ('4f60614a-1aca-5bbc-8509-05a30eda89a3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le message de Zoe, rapporté","competence":"manier-langue","situation":"Zoe envoie trois messages à sa mère. Celle-ci les rapporte ensuite à son père, une semaine plus tard.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Mum","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"I have finished my essay."},{"qui":"Zoe","texte":"I lost my bag at school."},{"qui":"Zoe","texte":"I have been waiting for the bus."},{"qui":"Mum","texte":"Poor you!"}],"source":"Messages écrits pour l’exercice"},{"id":"note","type":"texte","genre":"lettre","titre":"A note from Mum","blocs":["Dear Zoe, If I had known about your exam, I would have helped you. But nobody told me."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Relie chaque message de Zoe à sa version rapportée.","aide":"Au discours indirect, present perfect et prétérit deviennent tous les deux past perfect.","type":"association","gauche":[{"id":"g0","texte":"I have finished my essay."},{"id":"g1","texte":"I lost my bag at school."},{"id":"g2","texte":"I have been waiting for the bus."}],"droite":[{"id":"d0","texte":"She said she had lost her bag at school."},{"id":"d1","texte":"She said she had finished her essay."},{"id":"d2","texte":"She said she had been waiting for the bus."}]},{"enonce":"Rapporte le message sur le sac. Le premier mot est « Zoe ».","aide":"Sujet, verbe de parole, puis la phrase rapportée au past perfect.","type":"ordre","items":[{"id":"a","texte":"bag"},{"id":"b","texte":"said"},{"id":"c","texte":"had"},{"id":"d","texte":"her"},{"id":"e","texte":"she"},{"id":"f","texte":"Zoe"},{"id":"g","texte":"lost"}]},{"enonce":"Touche le participe passé de la subordonnée en « if ».","aide":"Il suit « had » juste après « If I ».","type":"zone","document":"note","multiple":false},{"enonce":"Que dit réellement la phrase de la mère ?","aide":"L’irréel du passé dit le contraire de ce qui s’est passé.","type":"choix","options":[{"id":"a","texte":"Elle aidera Zoe si elle apprend la date"},{"id":"b","texte":"Elle savait pour l’examen et elle a aidé Zoe"},{"id":"c","texte":"Elle ne savait pas et n’a donc pas aidé Zoe"},{"id":"d","texte":"Elle n’a pas voulu aider Zoe pour son examen"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Au discours indirect au passé, le present perfect et le prétérit deviennent un **past perfect** (*had finished*, *had lost*, *had been waiting*)."},{"cle":{"type":"ordre","ids":["f","b","e","c","g","d","a"]},"explication":"**Zoe said she had lost her bag** : le prétérit *lost* devient *had lost*."},{"cle":{"type":"zone","ids":["m5"]},"explication":"C’est **known** : *If I had known…* est un irréel du passé (past perfect après *if*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**If I had known, I would have helped** signifie : je ne savais pas, donc je n’ai pas aidé."}]$ex$::jsonb),
  ('4f60614a-1aca-5bbc-8509-05a30eda89a3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La tempête du vieux phare","competence":"se-reperer-temps","situation":"Dans le village imaginaire de Seaford, un phare a connu quatre événements. Un journaliste raconte la tempête de 2003 en remontant dans le temps.","documents":[{"id":"frise","type":"frise","titre":"The lighthouse timeline","debut":1995,"fin":2010,"pas":5,"evenements":[{"id":"z1","date":1998,"nom":"Keeper retires"},{"id":"z2","date":2001,"nom":"Lamp replaced"},{"id":"z3","date":2003,"nom":"Big storm"},{"id":"z4","date":2005,"nom":"Centre opens"}],"source":"Frise inventée pour l’exercice"},{"id":"article","type":"texte","genre":"article","titre":"Seaford Gazette","blocs":["When the storm hit the coast, Mr Hale had already retired. The council had replaced the lamp two years before, so the lighthouse still worked."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui correspond à « Mr Hale had already retired ».","aide":"C’est le plus ancien des événements racontés.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années avant la tempête la lampe avait-elle été remplacée ?","aide":"Compare les dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase d’un visiteur du centre, en 2005.","aide":"On remonte avant 2005 : past perfect.","type":"trous","segments":["When the centre opened, the storm ",0," ",1," the coast two years before."],"banque":["hit","has","had","hitting"]},{"enonce":"Complète la phrase sur le gardien.","aide":"On insiste sur la durée de l’action antérieure.","type":"trous","segments":["In 1999, Mr Hale was exhausted: he ",0," ",1," working for twelve hours."],"banque":["had","being","was","been"]},{"enonce":"Quelle phrase dit que la lampe a été remplacée AVANT la tempête ?","aide":"L’action la plus ancienne se met au past perfect.","type":"choix","options":[{"id":"a","texte":"When the storm hit, the council replaced the lamp."},{"id":"b","texte":"When the storm hit, the council had replaced the lamp."},{"id":"c","texte":"When the storm hit, the council has replaced the lamp."},{"id":"d","texte":"When the storm had hit, the council replaced the lamp."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Mr Hale est parti à la retraite en **1998**, bien avant la tempête de 2003."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 ans","explication":"2003 − 2001 = **2 ans** : *had replaced … two years before*."},{"cle":{"type":"trous","trous":[["had"],["hit"]]},"affichage":"had · hit","explication":"**had hit** : l’événement est antérieur à l’ouverture du centre (prétérit *opened*)."},{"cle":{"type":"trous","trous":[["had"],["been"]]},"affichage":"had · been","explication":"**had been working** : past perfect en BE + -ING pour la durée avant un état passé (*was exhausted*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**had replaced** est le fait antérieur ; *hit* au prétérit est le repère."}]$ex$::jsonb),
  ('7a189379-c8b5-50df-abda-78236985070d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un voyage à Dublin sous la pluie","competence":"comprendre-langue","situation":"Ruby et Finn organisent un voyage. Chaque phrase de leur échange parle de l’avenir d’une façon différente.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ruby","emoji":"👧","cote":"gauche"},{"nom":"Finn","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ruby","texte":"We’re flying to Dublin on Monday."},{"qui":"Finn","texte":"Look at the sky! It’s going to rain."},{"qui":"Ruby","texte":"My phone is ringing. I’ll answer it!"},{"qui":"Finn","texte":"The train leaves at six."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce une prédiction fondée sur ce qu’on voit dans le ciel.","aide":"La structure est be + ___ + to + verbe.","type":"zone","document":"sms","multiple":false},{"enonce":"Relie chaque phrase de l’échange à ce qu’elle exprime.","aide":"Pense à la forme verbale : -ING, going to, will, présent simple.","type":"association","gauche":[{"id":"g0","texte":"We’re flying to Dublin on Monday."},{"id":"g1","texte":"It’s going to rain."},{"id":"g2","texte":"I’ll answer it!"},{"id":"g3","texte":"The train leaves at six."}],"droite":[{"id":"d0","texte":"Une prédiction avec indice"},{"id":"d1","texte":"Un horaire officiel"},{"id":"d2","texte":"Une décision sur le moment"},{"id":"d3","texte":"Un programme fixé"}]},{"enonce":"Ruby décide sur le moment de répondre. Complète.","aide":"Une décision prise en parlant demande une forme précise.","type":"trous","segments":["The phone is ringing. I ",0," answer it."],"banque":["will","did","was","am"]}]}$ex$::jsonb,
