   $ex${"titre":"Trois situations, trois « if »","competence":"manier-langue","situation":"Trois élèves du lycée parlent de ce qui pourrait ou aurait pu se passer. Choisis la bonne structure pour chacun.","documents":[{"id":"situations","type":"tableau","titre":"Three situations","colonnes":["Who","What is happening"],"lignes":[["Ben","Rain is forecast for tomorrow: it may happen."],["Lia","She has no car today."],["Omar","He missed the bus last Monday."]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la situation passée qui ne peut plus changer (irréel du passé).","aide":"Cherche un verbe au prétérit et un jour déjà passé.","type":"zone","document":"situations","multiple":false},{"enonce":"Complète la phrase sur Lia (irréel du présent).","aide":"Après if, ni will ni would : le temps recule d’un cran.","type":"trous","segments":["If Lia ",0," a car, she would drive to work."],"banque":["will have","would have","had","has"]},{"enonce":"Quelle phrase sur Ben est correcte ?","aide":"Le fait est possible : type 1, présent après if.","type":"choix","options":[{"id":"a","texte":"If it rained tomorrow, Ben would have stayed in."},{"id":"b","texte":"If it would rain tomorrow, Ben will stay in."},{"id":"c","texte":"If it will rain tomorrow, Ben stays in."},{"id":"d","texte":"If it rains tomorrow, Ben will stay in."}],"multiple":false},{"enonce":"Range chaque phrase selon son type.","aide":"Regarde le temps après if : présent, prétérit ou past perfect.","type":"categories","categories":[{"id":"c0","texte":"Type 1"},{"id":"c1","texte":"Type 2"},{"id":"c2","texte":"Type 3"}],"items":[{"id":"i0","texte":"If she had called, I would have answered."},{"id":"i1","texte":"If I were rich, I would buy a villa."},{"id":"i2","texte":"If they had won, they would have celebrated."},{"id":"i3","texte":"If we had a garden, we would have a dog."},{"id":"i4","texte":"If it snows, we will ski."},{"id":"i5","texte":"If he studies, he will pass."}]}]}$ex$::jsonb,
