   $ex${"titre":"La sortie scolaire à York","competence":"analyser-document","situation":"Aisha et son professeur M. Reed préparent la sortie à York. Un tableau d’horaires et leurs messages disent ce qui est prévu.","documents":[{"id":"horaires","type":"fiche","modele":"horaires","entete":"Trip to York","sousTitre":"Friday","emoji":"🚌","lignes":[{"texte":"Coach leaves","valeur":"7.30 a.m.","id":"z1"},{"texte":"Coach arrives in York","valeur":"10.15 a.m.","id":"z2"},{"texte":"Meeting with the guide","valeur":"11.00 a.m.","id":"z3"}],"source":"Horaires imaginés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Aisha","emoji":"👧","cote":"gauche"},{"nom":"Mr Reed","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Aisha","texte":"The coach leaves at 7.30 tomorrow."},{"qui":"Mr Reed","texte":"Good. I’ll call the hotel as soon as we arrive."},{"qui":"Aisha","texte":"Look at the queue! We’re going to be late."},{"qui":"Mr Reed","texte":"We’re meeting the guide at eleven on Friday."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au présent qui exprime un futur après « as soon as ».","aide":"Après as soon as, on n’utilise pas will.","type":"zone","document":"sms","multiple":false},{"enonce":"Relie chaque phrase des messages à sa valeur.","aide":"Chaque forme a son sens : présent simple, will, be going to, présent en -ING.","type":"association","gauche":[{"id":"g0","texte":"The coach leaves at 7.30 tomorrow."},{"id":"g1","texte":"I’ll call the hotel…"},{"id":"g2","texte":"We’re going to be late."},{"id":"g3","texte":"We’re meeting the guide at eleven."}],"droite":[{"id":"d0","texte":"Une prédiction avec indice"},{"id":"d1","texte":"Une promesse, une décision"},{"id":"d2","texte":"Un programme fixé"},{"id":"d3","texte":"Un horaire officiel"}]},{"enonce":"Combien de minutes dure le trajet en car, d’après les horaires ?","aide":"De 7 h 30 à 10 h 15.","type":"nombre","unite":"minutes"},{"enonce":"Complète la phrase de M. Reed.","aide":"Type 1 : après if, le présent.","type":"trous","segments":["We will miss the guide if the coach ",0," late."],"banque":["will be","would be","were","is"]},{"enonce":"Remets en ordre la phrase d’Aisha. Le premier mot est « I’ll ».","aide":"La subordonnée en when reste au présent.","type":"ordre","items":[{"id":"a","texte":"get"},{"id":"b","texte":"I"},{"id":"c","texte":"text"},{"id":"d","texte":"when"},{"id":"e","texte":"you"},{"id":"f","texte":"I’ll"},{"id":"g","texte":"there"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**arrive** : après *as soon as*, on emploie le présent, jamais *will*."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Présent simple : horaire ; *will* : promesse ; *be going to* : indice visible (la queue) ; présent en -ING : programme daté."},{"cle":{"type":"nombre","valeur":165,"tolerance":0},"affichage":"165 minutes","explication":"De 7 h 30 à 10 h 15 : 2 h 45, soit 120 + 45 = **165 minutes**."},{"cle":{"type":"trous","trous":[["is"]]},"affichage":"is","explication":"**is** : après *if*, on emploie le présent pour parler de l’avenir (*if the coach is late*)."},{"cle":{"type":"ordre","ids":["f","c","e","d","b","a","g"]},"explication":"**I’ll text you when I get there** : *will* dans la principale, présent dans la subordonnée."}]$ex$::jsonb),
