   $ex${"titre":"Le nouveau professeur et la vitre brisée","competence":"manier-langue","situation":"Cara et Dev parlent du nouveau professeur, M. Wells. Un article de l’école raconte aussi une vitre brisée.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Cara","emoji":"👧","cote":"gauche"},{"nom":"Dev","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Cara","texte":"How is Mr Wells today? He was ill."},{"qui":"Dev","texte":"He’s better. He teaches us every Monday, doesn’t he?"},{"qui":"Cara","texte":"Yes. What is he like?"},{"qui":"Dev","texte":"Very patient and funny. He can’t sing, though."}],"source":"Messages écrits pour l’exercice"},{"id":"article","type":"texte","genre":"article","titre":"School news","blocs":["A window was broken at school on Friday. Mr Wells found the pieces and talked to the pupils. The caretaker saw a ball in the corridor. Nobody knows who broke it."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que Cara demande le caractère de M. Wells (et non sa santé).","aide":"On ne demande pas « comment va-t-il ? ».","type":"zone","document":"sms","multiple":false},{"enonce":"Complète le tag de Dev.","aide":"Phrase affirmative : tag négatif, avec l’auxiliaire do.","type":"trous","segments":["He teaches us every Monday, ",0," he?"],"banque":["doesn’t","hasn’t","does","isn’t"]},{"enonce":"Complète le tag.","aide":"Phrase négative : tag positif.","type":"trous","segments":["He can’t sing, ",0," he?"],"banque":["doesn’t","does","can","can’t"]},{"enonce":"Range chaque question selon la place du mot interrogatif.","aide":"Demande-toi si le mot interrogatif fait l’action ou la subit.","type":"categories","categories":[{"id":"c0","texte":"Sujet : pas d’auxiliaire"},{"id":"c1","texte":"Complément : auxiliaire obligatoire"}],"items":[{"id":"i0","texte":"Who did Mr Wells talk to?"},{"id":"i1","texte":"What did the caretaker see?"},{"id":"i2","texte":"Who found the pieces?"},{"id":"i3","texte":"Which ball hit the glass?"},{"id":"i4","texte":"Who broke the window?"}]}]}$ex$::jsonb,
