   $ex${"titre":"Une lettre depuis la plage de Brighton","competence":"comprendre-langue","situation":"Dans sa lettre, Nell s’exclame à plusieurs reprises. Repère comment commencent ses exclamations.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"A letter from Brighton","blocs":["Dear Mum,","What a beautiful beach this is! What lovely weather! How warm the sea is!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui ouvrent les exclamations de Nell.","aide":"Il n’y en a que deux différents : what et how.","type":"zone","document":"lettre","multiple":true},{"enonce":"Relie chaque exclamation à sa traduction.","aide":"What + nom, How + adjectif.","type":"association","gauche":[{"id":"g0","texte":"What a beautiful beach!"},{"id":"g1","texte":"What lovely weather!"},{"id":"g2","texte":"How warm the sea is!"}],"droite":[{"id":"d0","texte":"Que la mer est chaude !"},{"id":"d1","texte":"Quelle belle plage !"},{"id":"d2","texte":"Quel beau temps !"}]},{"enonce":"Complète l’exclamation sur le sable.","aide":"Après how, il faut un adjectif seul.","type":"trous","segments":["How ",0," the sand is!"],"banque":["a soft","soft","such","what"]}]}$ex$::jsonb,
