   $ex${"titre":"La kermesse, version Rita","competence":"analyser-document","situation":"Après la kermesse, plusieurs élèves ont écrit des exclamations, mais certaines contiennent une faute. Rita raconte aussi sa journée dans une lettre.","documents":[{"id":"liste","type":"tableau","titre":"Exclamations heard at the fair","colonnes":["Exclamation","Said by"],"lignes":[["What a mess this is!","Eli"],["What a mess is this!","Zack"],["How nice flowers!","Rita"],["What lovely flowers!","Max"],["It’s so cold!","Iris"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Rita’s letter","blocs":["Dear Aunt Jo,","What a day! The fair was such a success and the cakes were so delicious. How proudly Max sold them!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux exclamations fausses.","aide":"L’une inverse sujet et verbe ; l’autre emploie le mauvais mot devant un nom.","type":"zone","document":"liste","multiple":true},{"enonce":"Pourquoi « What a mess is this! » est-elle fausse ?","aide":"Compare avec la phrase d’Eli.","type":"choix","options":[{"id":"a","texte":"Il faut remplacer what par how devant un nom"},{"id":"b","texte":"L’article a est interdit devant le mot mess"},{"id":"c","texte":"Sujet et verbe ne s’inversent pas dans une exclamation"},{"id":"d","texte":"Le verbe doit être au prétérit dans une exclamation"}],"multiple":false},{"enonce":"Corrige la phrase de Rita.","aide":"Des fleurs, c’est un nom au pluriel.","type":"trous","segments":[0," nice flowers!"],"banque":["So","What","How","A"]},{"enonce":"Touche les deux mots (adjectif et adverbe) qui suivent so ou how dans la lettre de Rita.","aide":"« Success » est un nom : ne le touche pas.","type":"zone","document":"lettre","multiple":true}]}$ex$::jsonb,
