   $ex${"titre":"Chaque jour plus froid","competence":"analyser-document","situation":"Leo et Mia suivent la météo d’une semaine d’hiver. La courbe donne la température à 6 heures du matin.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Temperature at 6 a.m.","categories":["Mon","Tue","Wed","Thu","Fri"],"series":[{"nom":"Temperature","valeurs":[11,8,6,2,4],"teinte":"bleu"}],"axeY":{"titre":"Temperature","unite":"°C","min":0,"max":12,"pas":2},"source":"Valeurs inventées pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Leo","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leo","texte":"Tuesday was colder than Monday."},{"qui":"Mia","texte":"And Thursday was the coldest day of the week!"},{"qui":"Leo","texte":"It’s getting colder and colder."},{"qui":"Mia","texte":"The colder it gets, the more hot chocolate I drink."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Mia dit que c’était le jour le plus froid : touche le point de la courbe qui le confirme.","aide":"Cherche la température la plus basse.","type":"zone","document":"courbe","multiple":false},{"enonce":"Combien de degrés de moins le jeudi que le lundi ?","aide":"Lis les deux températures sur la courbe.","type":"nombre","unite":"°C"},{"enonce":"Compare vendredi (4 °C) et jeudi (2 °C).","aide":"Vendredi est un peu moins froid que jeudi.","type":"trous","segments":["Friday was ",0," as cold as Thursday."],"banque":["much","very","more","not"]},{"enonce":"Quelle phrase sur mercredi (6 °C) est correcte ?","aide":"Place 6 entre les valeurs de mardi et de jeudi.","type":"choix","options":[{"id":"a","texte":"Wednesday was colder than Tuesday but warmer than Thursday."},{"id":"b","texte":"Wednesday was as cold as Monday this week."},{"id":"c","texte":"Wednesday was colder than Thursday but warmer than Tuesday."},{"id":"d","texte":"Wednesday was the coldest day of the week."}],"multiple":false},{"enonce":"Complète la phrase de Mia.","aide":"Structure de proportion : the + comparatif, the + comparatif.","type":"trous","segments":["The colder it gets, the ",0," hot chocolate Mia drinks."],"banque":["many","more","much","most"]}]}$ex$::jsonb,
