e « Photos are forbidden unless a guide agrees » ?","aide":"Unless contient déjà une négation : « si … ne … pas ».","type":"choix","options":[{"id":"a","texte":"Les photos sont interdites sauf si un guide est d’accord"},{"id":"b","texte":"Les photos sont interdites parce qu’un guide est présent"},{"id":"c","texte":"Les photos sont interdites même si un guide est d’accord"},{"id":"d","texte":"Les photos sont autorisées dès qu’un guide est présent"}],"multiple":false}]}$ex$::jsonb,
